window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_013"]={"n":"缪公恩","dyn":"清","poems":[{"t":"题画","f":"五言绝句","c":["茅屋两三间，云横千仞山。","西风下残照，烟水片帆还。"]},{"t":"秋日游冯氏废园","f":"五言律诗","c":["溪水环村舍，门迎杜若洲。","清风三径晓，黄叶一庭秋。","霜度征鸿远，墙吟促织幽。","故园何处是，引起别离愁。"]},{"t":"溪上","f":"七言绝句","c":["霜气横秋木叶残，夕阳雁影下芦滩。","茅堂寂寂人高卧，门外云深水自寒。"]},{"t":"春日郊游","f":"五言律诗","c":["出城三四里，茅舍几人家。","踏屐探幽径，敲门问落花。","风前村店酒，雨后小姑茶。","处处多春涨，桃源拟泛槎。"]},{"t":"春闺","f":"七言绝句","c":["冷雨凄凄独掩扉，无言脉脉望春归。","桃花柳絮关情思，莫逐东风一片飞。"]},{"t":"月下闻笛","f":"五言律诗","c":["何处吹羌笛，萧然到草亭。","烟轻笼淡月，云薄带疏星。","一曲催梅落，三秋折柳青。","援琴方欲和，雁阵下寒汀。"]},{"t":"舟泊焦山作","f":"五言律诗","c":["晴光明素镜，皎月海门浮。","蜃气朝成雾，龙吟夜入秋。","十年常作客，万里一维舟。","凭吊蜗庐叟，低回意欲留。"]},{"t":"春闺","f":"七言绝句","c":["千树桃花映粉楼，东风万点逐波流。","落红不是题诗叶，愁向人间寄得不。"]},{"t":"水阁纳凉同董均可步管丈秋崖元韵","f":"七言律诗","c":["一泓秋涨半池荷，小榭临流起细波。","水气潜随花气散，蝉声远杂树声多。","残霞影落连朱槛，新霁烟深锁翠萝。","纳爽不知天竟晚，已看高阁转银河。"]},{"t":"前题答董均可","f":"七言律诗","c":["小阁清幽绕芰荷，生香十里漾层波。","雨侵石壁吟蛩少，风拂寒林野茧多。","断港残晖留几榻，平桥衰柳伴藤萝。","长歌久出巴人下，一曲淇原隔大河。"]},{"t":"寒月","f":"七言律诗","c":["仙宇萧骚转玉绳，西风淅淅夜澄澄。","光飞碧瓦千家雪，影挂银河一片冰。","潮落海天秋气敛，烟销云汉露华凝。","嫦娥罢舞开妆镜，霜重霓裳力不胜。"]},{"t":"读张瀛客先生遗稿","f":"七言律诗","c":["炉冶群言自一家，夜台萧索两年赊。","古梅雅抱凭谁赏，宝剑寒芒空自嗟。","手迹只馀书上草，心思犹灿笔头花。","遥怜麦饭青松树，黯淡残阳噪晚鸦。"]},{"t":"登辛峰亭","f":"七言律诗","c":["孤亭峭立压嵯峨，尺五青霄近可摩。","地涌湖光飞匹练，云连海气锁双螺。","珠襦香散红颜冷，宝剑虹藏碧草多。","欲问遗踪何处是，清风飒飒拂藤萝。"]},{"t":"夜坐","f":"古风","c":["一天风雨暗雕檐，古鼎香残细细添。","官酿初开陶令酒，山园小熟戴公柑。","贪看菊影频移榻，为待蟾光不下?。","谯鼓沈沈乡梦杳，客窗新韵几回拈。"]},{"t":"漫吟","f":"古风","c":["梧桐瑟瑟竹萧萧，閒捲湘?坐寂寥。","碎响何来清彻耳，半窗疏雨打芭蕉。"]},{"t":"游虎邱","f":"七言律诗","c":["附郭名山著虎邱，繁华未始掩清幽。","画船十里联红袖，歌管千家起翠楼。","云气自来萦塔影，岚光终古落溪流。","讲台不复生公坐，顽石何时再点头。"]},{"t":"立夏前偶成","f":"五言绝句","c":["入夏馀三日，春光有几何。","鸟声宿雨少，花瓣落风多。"]},{"t":"舟行湖中","f":"五言律诗","c":["万里轻舠返，平湖正暮秋。","沙汀来雁阵，荻港动渔舟。","山影天边淡，村烟水际浮。","息心争席后，倚棹狎群鸥。"]},{"t":"江中","f":"七言律诗","c":["镜里行人画里舟，篷窗深锁半江秋。","气吞巫峡三千里，声到蓬壶十二楼。","山隔天光迷两脚，日蒸霞影破云头。","布帆风利难停泊，未许金焦汗漫游。"]},{"t":"环翠楼闻篴","f":"七言绝句","c":["草短沙平雁下滩，小楼初夜凭阑干。","月明何处吹渔篴，秋水梅花一味寒。"]},{"t":"翠峰寺","f":"七言绝句","c":["古刹依山竹绕楼，岚光飞黛结松楸。","老僧不解谈经偈，但向青峦说石头。"]},{"t":"黄浦江待渡","f":"七言绝句","c":["出没江豚拜碧澜，篷窗薄暮倚阑干。","怒潮忽向天边起，一夜涛声枕上寒。"]},{"t":"太湖怀古 其一","f":"五言绝句","c":["扁舟泛五湖，倚棹望姑苏。","嗟哉伍相国，不及范大夫。"]},{"t":"太湖怀古 其二","f":"五言绝句","c":["扁舟泛五湖，倚棹望越都。","嗟哉吴西施，不及秦罗敷。"]},{"t":"纳凉","f":"七言绝句","c":["平池倒影落霞红，碎锦残花入镜中。","小榭临流窗四面，袭人衣袖紫薇风。"]},{"t":"登楼","f":"七言律诗","c":["落叶萧条万井秋，碧云天外水东流。","苍烟古木寒鸦乱，野径残阳旅客愁。","千里音书悲雁断，十年踪迹感萍浮。","擎杯欲醉何曾醉，惆怅西风独倚楼。"]},{"t":"寄贾丈汉庭 其一","f":"七言绝句","c":["吴淞烟水隔伊人，几度西楼望月轮。","不信陇头无驿使，也应寄我一枝春。"]},{"t":"寄贾丈汉庭 其二","f":"七言绝句","c":["今岁山梅特早开，北枝已是点冰苔。","墙阴一树封残雪，笋脆芹香待客来。"]},{"t":"送别友人","f":"七言律诗","c":["海风吹雨满山城，小艇蒲帆送客行。","花落沙堤春草绿，水深野港暮潮平。","一樽酒尽难言别，千里人归太瘦生。","北雁有书须远寄，莫教江树锁离情。"]},{"t":"途中","f":"七言绝句","c":["天外青山隐夕阳，烟波缥缈忆江乡。","白云无路归鸿鹄，海燕翩翩底事忙。"]},{"t":"野店","f":"七言绝句","c":["柳浪青青麦浪黄，山风吹雨湿衣裳。","微尘不起茆檐洁，野枣花开树树香。"]},{"t":"寄怀友人","f":"七言绝句","c":["碧空银汉锁天津，万里西风独惘神。","愿诉愁心付明月，殷勤寄与倚栏人。"]},{"t":"闱中作","f":"七言绝句","c":["碧汉无声万里清，浩然风露夜三更。","南天极目空相忆，明远楼头月正明。"]},{"t":"过玉蝀桥","f":"七言绝句","c":["御池秋水碧潾潾，万树迎风拥翠尘。","蓦地天香来水面，此身应是月中人。"]},{"t":"九月七日作","f":"五言律诗","c":["弓月悬星汉，寒光落万家。","蛩吟清露重，雁带碧天斜。","父母怜游子，关山感物华。","徘徊明镜里，举首望浮槎。"]},{"t":"饮酒","f":"五言律诗","c":["春暮发轻舟，旋惊报九秋。","西风吹落木，寒月下高楼。","空负千金剑，难销万斛愁。","谁家有美酒，不惜紫貂裘。"]},{"t":"远望","f":"七言绝句","c":["青山断处白云遮，山外遥空雁阵斜。","万里西风吹落叶，不吹客梦到天涯。"]},{"t":"晓至赵北口","f":"七言律诗","c":["短烛烧残马暂停，渡头村舍户犹扃。","鸡声警露鸣高树，雁阵排空下远汀。","两岸芦花飞白雪，半湖秋水带寒星。","凭栏欲济无舟楫，目极遥山一抹青。"]},{"t":"吊谷城项王冢","f":"七言律诗","c":["谷城山下路苍苍，独对高峰吊愤王。","当日拔山矜意气，祇今残陇牧牛羊。","风声悲似骓嘶月，岚色寒犹剑吐芒。","空养全锋誇得鹿，长陵秋草几斜阳。"]},{"t":"道中","f":"七言绝句","c":["敝裘不耐晓来凉，风捲黄沙啸白杨。","极目遥天空怅望，马嘶声里又残阳。"]},{"t":"夜坐","f":"七言绝句","c":["雁断秋空一纸书，旅人惆怅意何如。","夜深自起当轩坐，明月萧萧落碧梧。"]},{"t":"谒和圣柳下惠墓","f":"七言律诗","c":["展季坟前歧路多，村童笑指此间过。","士存抔土争王贵，人沐遗风识圣和。","柳外轻烟归牧笛，洲边细雨隐渔蓑。","双槐墓道盘根大，十万龙蛇效护呵。"]},{"t":"途间怀洪稚存书壁","f":"七言律诗","c":["乡关迢递阻离思，冀马南风鸟北枝。","嗟我又来黄叶路，忆君同听白杨时。","凉云落照三秋别，野草平沙万里悲。","他日花骢重此过，休忘索和壁间诗。"]},{"t":"途中二律 其一","f":"五言律诗","c":["茆店鸡初唱，长堤策马过。","水明残月出，霜重晓寒多。","夹道迷荒草，连天涌白波。","敝裘谁补缀，萧瑟奈秋何。"]},{"t":"途中二律 其二","f":"五言律诗","c":["羁迟踰半载，游子意如何。","清梦白云远，征鞍黄叶多。","万山飞晓月，平野落秋河。","古道无相识，愁心寄素娥。"]},{"t":"春怨","f":"七言绝句","c":["和风吹絮夕阳西，嫩柳千条一色齐。","何事东君归去早，落红满径子规啼。"]},{"t":"广陵竹枝词","f":"七言绝句","c":["从来洋子桥头水，不向江都城外流。","愿诉潮神与风伯，殷勤为我送郎舟。"]},{"t":"翁仲","f":"七言律诗","c":["剑佩衣冠恰俨然，昂藏尽日对苍烟。","不言浑似三缄后，僵立何曾一步前。","墓道草深无麦饭，纸灰风散落榆钱。","牧人来往谁相问，任遣牛羊陇下眠。"]},{"t":"舟中远望","f":"七言律诗","c":["极目青青麦陇齐，遥空山锁碧云低。","一天春水江豚拜，万树垂杨杜宇啼。","怪底愁心偏酒醉，缘何燕子入舟栖。","计来旬日才瓜步，未得扬帆日又西。"]},{"t":"扬州 其一","f":"七言绝句","c":["自古扬州明月多，我来风雨锁嫦娥。","桥边阁子谁家笛，短调偏吹折柳歌。"]},{"t":"扬州 其二","f":"七言绝句","c":["洋子江潮向夕平，画樯粉黛竞春行。","何人廿四桥头立，折取琼花贮玉瓶。"]},{"t":"途中","f":"五言律诗","c":["策马拂征裳，微风料峭凉。","月残人影淡，露重枣花香。","已是经旬别，徒劳寸结肠。","夜来茆屋里，清梦绕华堂。"]},{"t":"乞活城","f":"七言绝句","c":["铁甲雕戈委战尘，将军一败弃君亲。","孤城乞活今安在，何似田横五百人。"]},{"t":"督亢亭","f":"七言绝句","c":["竟将督亢入秦庭，太子宁知事不成。","丽室已随流水去，孤亭犹有暮烟横。"]},{"t":"过易水","f":"七言绝句","c":["易水潇潇日夜流，霜锋未发一身休。","可怜怒叱燕丹去，不及秦州乌白头。"]},{"t":"都中见洪稚存 其一","f":"五言律诗","c":["燕市君居久，咄哉吾又来。","半窗摊卷轴，小户远尘埃。","病马谁相问，征衣母自裁。","擎杯空怅望，偕子陟金台。"]},{"t":"都中见洪稚存 其二","f":"五言律诗","c":["半载离愁结，连床片刻消。","暂邀青眼顾，又望白云遥。","有梦都萧瑟，逢场亦寂寥。","知君同此意，共忆路迢迢。"]},{"t":"书洪稚存近作后","f":"五言律诗","c":["乾坤大如此，晴雨又何奇。","上下阅千古，荣枯任四时。","云空飞逸气，月皎见清思。","燕赵吾桑梓，能歌慷慨词。"]},{"t":"暮霁对月","f":"七言律诗","c":["残云归岫碧天空，碧瓦烟迷夕照红。","雨气凉生深苑月，箫声吹彻小楼风。","材惭燕市千金骨，梦绕吴门半夜钟。","好向人□求玉斧，客星已傍广寒宫。"]},{"t":"寺中夜晴","f":"七言律诗","c":["云关寂寂锁幽昙，鸳瓦新晴色倍蓝。","万里碧空收暮雨，满楼明月忆江南。","桃笙梦醒闻街柝，竹寺钟疏落枕函。","起看玉绳天外堕，绿窗槐影露华酣。"]},{"t":"期洪稚存相过久不赴约因寄以诗","f":"七言律诗","c":["雨砌连朝长绿苔，摛词检字费宏才。","子猷不放山阴棹，陆凯空劳驿使梅。","月落屋梁思黯澹，酒醒冰簟起徘徊。","嘱君好拂窗前几，明日携樽有客来。"]},{"t":"寺中忆洪稚存不至","f":"五言古诗","c":["炎热不可避，来与山僧邻。","虚窗清以幽，砌草如铺茵。","长槐结空翠，落我砚池滨。","邻僧少禅说，往来多俗人。","安得青松风，扫此阶前尘。","携我故人来，饮我尊中醇。","吟诗或终夕，清谭或经旬。","披襟坐北窗，啸傲当冰轮。","故人久不来，微飙动丛筠。"]},{"t":"途中","f":"五言律诗","c":["频岁劳征辔，来归又九秋。","鸡声惊客梦，雁字动乡愁。","野水明残月，寒烟隐戍楼。","故人多不贱，憔悴敝貂裘。"]},{"t":"太湖","f":"五言古诗","c":["沧波渺无际，群山浮镜中。","上无青云梯，下有苍龙宫。","澒洞撼大地，飘忽来长风。","灵威忆仙迹，底定钦神功。","悲哉伍相国，远矣陶朱公。","智勇尽合轨，生死皆英雄。","人生托天地，踪迹如飞蓬。","壮游在适意，无为悲穷通。","古人不可见，旦暮行将终。","一艇破碧烟，双桨淩虚空。","焉得天汉槎，聊此寄空濛。"]},{"t":"对月感怀","f":"七言律诗","c":["镫锁寒光树锁烟，小楼寥廓独萧然。","九峰有梦人千里，万瓦无声月满天。","酒醉剑鸣空饮泣，夜深鸡舞不成眠。","壮心岁暮谁堪语，搔首长歌付短笺。"]},{"t":"暮坐偶成兼忆洪大","f":"七言律诗","c":["云冻长空万籁收，暮烟凝碧入层楼。","千林野树森霜气，半榻青灯冷月钩。","雁去诗成难寄远，夜寒酒薄不降愁。","故人一别无消息，回首燕台天际头。"]},{"t":"斋中即事和上逵韵","f":"五言律诗","c":["幽轩无俗物，庭院少人来。","石竹含残雨，山梅破冻苔。","局成棋阵列，汤沸茗旗开。","清韵堪酬唱，何须觅酒杯。"]},{"t":"冬夜坐月上逵韵","f":"五言律诗","c":["月明浑似水，万瓦冷霜飞。","夜静人声寂，天寒酒力微。","梦回乡国远，雁断信音稀。","坐久梅花影，横斜满竹扉。"]},{"t":"叠前韵","f":"五言律诗","c":["老树寒明月，庭空乌鹊飞。","书劳千里远，身寄一枝微。","弱骨梅花瘦，诗情砌草稀。","故人天际外，惆怅对窗扉。"]},{"t":"泊舟江中","f":"七言律诗","c":["江心薄暮系吴舲，岚气横空暗翠屏。","隔浦风声来远笛，拍天波影乱繁星。","三更月涌潮头白，两点山开水面青。","路阻蓬瀛飞不到，篷窗清梦绕疏棂。"]},{"t":"金山","f":"七言律诗","c":["孤帆横渡破江烟，氐父山根泊画船。","金粉远离尘世劫，楼台常浸水云天。","更无人觅披沙果，空有僧传解带缘。","栏外萧萧秋雨歇，冲冠长啸忆当年。"]},{"t":"登凤凰山远望大江","f":"七言律诗","c":["凤凰山对凤凰台，曳屐攀援破紫苔。","长堑当年称地险，石门终古向天开。","孤帆云尽横江去，九镇春深细雨来。","莫望长安愁日暮，乡关乘兴且徘徊。"]},{"t":"虞姬墓词","f":"楚辞体","c":["长江涌浪吊雄风，何处纤腰问楚宫。","脉脉水云低晚翠，夭夭桃树艳春红。","村人指我城西路，高原遗有当年墓。","至今父老久传闻，虞兮在昔埋魂处。","重围四起楚些声，拔剑悲歌骓不行。","盖世英雄意气尽，美人泣下不胜情。","大王起饮帐中酒，美人点点低垂首。","此时善战竟何如，空向鸿门思玉斗。","我来墓下揖斜阳，羡杀重瞳叹汉王。","吕雉不贞人彘枉，美人抔土姓名香。","即今寄魄坟边草，红苞灼灼柔枝袅。","此是千秋烈女身，等閒蜂蝶休相扰。","悤悤戎马瘗婵娟，玉匣珠襦事罔传。","自是美人甘遂死，不妨藁草置荒田。","美人虽死芳声在，只惜龙门书不载。","欲将往事问青山，青山不语愁春黛。"]},{"t":"题画蝶赠成丈宝林","f":"七言律诗","c":["七十临滁老画师，孤高品格岁寒姿。","沈心自撰南华注，遣兴还书无逸诗。","衣剪东风春料峭，梦回芳草雨葳蕤。","滕王秘本无消息，输与江城钓叟知。"]},{"t":"寄黄韭畦","f":"七言律诗","c":["沧江地僻无佳客，雨落狂花满敝庐。","端节忆逢车马至，春风乍领笑谈馀。","衙荒不具洪州榻，性鲁空闻圮上书。","惆怅灵岩天外碧，双峰新月对庭除。"]},{"t":"秋暮怀洪稚存","f":"五言古诗","c":["秋风何萧萧，木叶纷以飞。","时序忽已更，缅彼百卉腓。","出步空庭前，残阳明短扉。","俯仰空踟躇，悠然有所思。","故人久行役，乃在天之涯。","忆昔大河边，行色共悽悽。","接谈倾盖间，遂订白首期。","空山项王坟，荒草荀令碑。","白杨啸晚风，其声亦何悲。","与子话平生，泣下各沾衣。","旅食黄金台，两度伤别离。","子乃化鹏去，我还趋庭帏。","音问一以隔，闻入三秦畿。","西北气候早，七月黄沙吹。","帷幕多凉风，夜深镫火微。","愿言思故人，弹铗歌来归。"]},{"t":"晚登凤凰山归作","f":"七言律诗","c":["石磴云萝手自扪，披襟独眺凤凰墩。","寒烟日暮埋山骨，白露秋深冻草根。","雁阵排空风断续，鸦声绕树月黄昏。","一镫归向窗前坐，竹影离离悄闭门。"]},{"t":"对酒有怀洪稚存","f":"七言律诗","c":["萧瑟西风冷敝貂，携樽燕市雨潇潇。","故人已别千山外，游子空归万里遥。","近日秦中书未达，比年髀里肉全消。","何时再对东窗月，百斛离愁一醉销。"]},{"t":"病中","f":"古风","c":["闻说官梅破冻苔，风?隔断暗香来。","一庭明月横花影，蠡卖窗寒不敢开。"]},{"t":"定山","f":"七言绝句","c":["石印遗踪恰宛然，山名遂以达摩传。","举头峭壁三千丈，撒手应知又一天。"]},{"t":"桃叶渡","f":"五言绝句","c":["桃叶几时去，桃花今尚开。","只馀溪上水，曾照美人来。"]},{"t":"送周君敦庵 其一","f":"七言绝句","c":["江绕青山山绕城，清溪古柳拂波平。","河桥到处飘青幔，多少依依挽客情。"]},{"t":"送周君敦庵 其二","f":"七言绝句","c":["故人酒尽横江上，薄暮云消碧海东。","此去江湖万馀里，封姨莫助石尤风。"]},{"t":"北门晚步","f":"七言律诗","c":["曳杖残阳出北门，芊芊芳草没沙痕。","万重浓翠围高垒，一缕轻烟上远村。","牛载篴声林外去，日迷云影陇头昏。","西华岚翠连天起，迢递峰峦不可扪。"]},{"t":"至白马寺观陈白沙庄定山诗碑","f":"七言律诗","c":["断水鳞鳞起碧烟，寻碑古寺访高贤。","秋蛇春蚓数行字，苔蚀尘封三百年。","椎鲁未堪称后学，摩挲应是有前缘。","漫将儒墨疑形迹，不害昌黎友大颠。"]},{"t":"归自白马寺途中成咏","f":"七言律诗","c":["残阳半挂碧峰头，野水萦洄萧寺流。","竹绕颓垣荒径僻，苔封片石古文留。","榴花艳艳开茆屋，杨柳阴阴隐佛楼。","弄月归来扳绝磴，苍苍岚翠拂衣浮。"]},{"t":"秋夜对月","f":"七言律诗","c":["白露初团未结霜，萧萧木叶打衣裳。","青山落影千峰淡，明月无声万瓦凉。","笛里何人吹折柳，楼头有客恰思乡。","远书欲寄凭谁达，天末风高断雁行。"]},{"t":"夜坐","f":"五言律诗","c":["木落小窗空，云消碧海东。","露华浮夜月，星影动天风。","旅梦关山远，羁愁黯淡中。","一镫殊寂寂，倚户听飞鸿。"]},{"t":"别李绮琴","f":"五言律诗","c":["抚兹松与竹，相顾犹依依。","况乃故人情，弃之宁如遗。","赖此怀袖间，常有一编诗。","朝夕对行橐，聊以慰相思。"]},{"t":"江浦留别 其一","f":"七言律诗","c":["浪游到处感离群，几度骊歌讵忍闻。","十六年来犹故我，五千里外忆诸君。","白门望眼迷烟树，吴下愁心隔暮云。","别绪匆匆吟不得，那堪红雨更纷纷。"]},{"t":"江浦留别 其二","f":"七言律诗","c":["一番惆怅独徘徊，何日扁舟我再来。","岁月半从愁里去，烟花空向眼前开。","浪传乌桕欢能合，谁信飞星往不回。","百结枯肠真欲断，长吟且覆掌中杯。"]},{"t":"江浦留别 其三","f":"七言律诗","c":["江干碧涨一篙匀，细雨才晴柳色新。","芳草连天无奈别，落花满地可怜春。","篷窗镫影听渔篴，马足风声起辙尘。","驿壁从今题句去，未知属和是何人。"]},{"t":"江浦留别 其四","f":"七言律诗","c":["临歧为语莫伤神，聚散应知有夙因。","万里尚劳天外梦，一枝须寄陇头人。","春潮浩浩催舟急，杜宇声声促客频。","回首山城残照里，满江波浪碧无垠。"]},{"t":"阻风燕子矶","f":"七言绝句","c":["夜色凄其水气寒，怒潮风急拍天宽。","可怜燕子矶头月，多少愁人倚棹看。"]},{"t":"放舟","f":"七言律诗","c":["溶溶春水大江平，风定深宵曙色晴。","两岸山飞双橹急，中流人稳一舟轻。","日烘晓色云霞丽，天入澄波锦绣明。","连夕封姨偏肆虐，今朝指顾到芜城。"]},{"t":"歌风台","f":"七言绝句","c":["大风不独忆淮阴，云影飞扬自古今。","我上高台舒远啸，茫茫何处问馀音。"]},{"t":"挂剑台","f":"五言绝句","c":["挂剑浑无迹，荒台自古今。","即看原上草，想见古人心。"]},{"t":"芙蓉","f":"七言绝句","c":["忆得当年沼上栽，粉红霜洗净无埃。","不知画桨人归去，又向西风几度开。"]},{"t":"都中留别兼送入试","f":"七言律诗","c":["桂影西风几度经，此身鹿鹿竟何成。","一镫我醉清樽酒，千里谁怜野店情。","句警片言金鼎重，兴酣椽笔雁毛轻。","不知明远楼头月，可向天涯一样明。"]},{"t":"过背阴铺 其一","f":"五言律诗","c":["扰扰风尘里，驰驱废咏吟。","乾坤开异境，山水豁灵心。","云色环青嶂，溪声泻素琴。","苍茫深树里，岭背霭轻阴。"]},{"t":"过背阴铺 其二","f":"五言律诗","c":["石径白皑皑，车轮碾翠苔。","路从山脚断，屋向树头开。","峰影连窗暗，岚光扑面来。","何当一栖息，曳屐暂徘徊。"]},{"t":"过十三山","f":"七言绝句","c":["一鞭晓过锦川城，驴背风来料峭轻。","吹尽暮云天宇净，十三山上月初明。"]},{"t":"杏山","f":"七言律诗","c":["牧马萧萧齧草芽，乱峰历历夕阳斜。","气沈宝剑埋黄土，骨冷青燐走碧沙。","此日有人多击壤，当年何地不吹笳。","春来犹见山前杏，笑向东风烂漫花。"]},{"t":"姜女庙","f":"七言绝句","c":["乱石长廊锁寂寥，冻云野树日萧萧。","我来遗迹谁堪问，门外寒波落晚潮。"]},{"t":"昭君 其一","f":"七言绝句","c":["莫嗟薄命事和戎，忍泪扶鞍出汉宫。","长信月明清露冷，有人团扇泣秋风。"]},{"t":"昭君 其二","f":"七言绝句","c":["十九星霜羁北海，五千貂锦没全营。","汉庭莫罪毛延寿，一遣蛾眉小太平。"]},{"t":"归途度岁","f":"七言律诗","c":["京华冲雪路频经，待得归来岁欲更。","烟锁荒村残日落，天低石栈冻云平。","愁魂摇乱寒镫影，旅梦惊回爆竹声。","为祝高堂休怅望，征人已在第三程。"]},{"t":"春日怀旧","f":"七言律诗","c":["东风吹散绿杨烟，乱落閒庭榆荚钱。","今日旧巢看乳燕，昨年残梦醒啼鹃。","寄书有客来天末，对酒何人在目前。","万里归来成契阔，烟花独赏亦凄然。"]},{"t":"怀成宝林","f":"七言律诗","c":["纸窗树影日初斜，为忆南园满树花。","嗟我风尘劳寤寐，有人城市饱烟霞。","谁将消息传春雁，空使愁心动暮笳。","昨夜月明身似蝶，梦魂万里到君家。"]},{"t":"山居","f":"七言律诗","c":["青山深处草堂开，面面峰峦拥翠来。","短榻临风当槛坐，野花乘雨傍篱栽。","参差树影迷樵径，清冷泉声到钓台。","随意徘徊随量醉，人间何事觉蓬莱。"]},{"t":"山居杂咏 其一","f":"七言绝句","c":["落落山村远俗纷，柴关静掩日初曛。","閒窗吟倦浑无事，卧对青峰看白云。"]},{"t":"山居杂咏 其二","f":"七言绝句","c":["山风野树晚生凉，岚气飞来罨水光。","步向南峰望明月，绿畴千顷尽如霜。"]},{"t":"山居杂咏 其三","f":"七言绝句","c":["一带云光绿树连，万峰浓锁夕阳烟。","夜深雨气来何许，忽听溪声到枕边。"]},{"t":"怀李绮琴","f":"七言绝句","c":["莲塘闻在碧江头，载酒寻诗约共游。","今见花开人不见，何时重上木兰舟。"]},{"t":"秋夜怀洪稚存","f":"五言古诗","c":["明月何皎皎，良夜何迟迟。","牛女隔绛河，风露凉凄其。","清光照人间，何处无别离。","长歌寄所怀，乃在天之涯。","披衣步空庭，木叶横天飞。","不知游子心，此时何所思。"]},{"t":"落叶","f":"七言律诗","c":["秋色无尘树影凉，泬寥天宇暗飞霜。","忽将枝上千重翠，散作阶前万点黄。","蝴蝶乱翻来小苑，芭蕉碎响入虚堂。","莫将摇落伤萧瑟，请看枫林灿夕阳。"]},{"t":"菊花","f":"七言绝句","c":["为寻佳种几徘徊，手取灵根绕砌栽。","孤负重阳时节好，连朝风雨不曾开。"]},{"t":"冬夜","f":"五言律诗","c":["杯空炉火尽，深夜一镫残。","雪影疏窗白，风声晓漏寒。","俗缘居近市，贫尚食充箪。","惭愧青毡破，终宵感百端。"]},{"t":"寄薛君公望","f":"七言律诗","c":["东风又舞绿杨枝，春雨楼前赠我时。","四载星霜人契阔，五湖烟水梦迷离。","废书俗骨应难药，对酒愁心尚可医。","如有新题附归雁，愿将小楷界乌丝。"]},{"t":"寄孙君水南 其一","f":"七言绝句","c":["沧浪亭北乐桥东，门闭垂杨几树风。","五日三餐浑不计，老妻犹为整诗筒。"]},{"t":"寄孙君水南 其二","f":"七言绝句","c":["制锦才华老更雄，几经卖赋尚愁穷。","近年目力还佳否，铁线乌丝可复工。"]},{"t":"万泉河步月","f":"七言绝句","c":["碧空千里火云流，风断残虹暮雨收。","深夜老龙眠不得，海天抛上水晶球。"]},{"t":"长干曲 其一","f":"五言绝句","c":["采莲清溪口，不似在横塘。","相逢不相识，且莫诉中肠。"]},{"t":"长干曲 其二","f":"五言绝句","c":["我向清溪来，郎往横塘去。","双桨未相逢，花深在何处。"]},{"t":"仿西昆体","f":"七言律诗","c":["金井飞霜素绠寒，银瓶夜汲玉阑干。","碧梧叶落难栖凤，宝镜奁深不照鸾。","常拣丹沙藏蜥蜴，少娴刀尺制罗纨。","徘徊锦瑟遮秋扇，盥手中宵未敢弹。"]},{"t":"怀洪稚存在陕","f":"七言律诗","c":["历游五岳竟如何，岁月堂堂瞬息过。","少室云中看太华，孤城天上落黄河。","一樽话别三秋末，万里投书六载多。","近日长安曾到否，故人遥望苦吟哦。"]},{"t":"夜读","f":"七言绝句","c":["风声瑟瑟漏漫漫，镫暗兰膏荻火残。","读到夜深人静后，半轮月上纸窗寒。"]},{"t":"题画","f":"五言绝句","c":["古殿开孤岫，疏林带远岑。","伊人在何处，秋水碧云深。"]},{"t":"忆镇江府经历司署","f":"七言绝句","c":["几竿修竹绕吾庐，冷署无人静读书。","昨日江船新下网，楝花风里上□鱼。"]},{"t":"忆夜过松江府","f":"七言绝句","c":["轻风五雨汎轻舠，柳映花遮秀野桥。","明月一天澄似水，水云亭外夜迢迢。"]},{"t":"忆渡太湖","f":"七言绝句","c":["我亦扁舟汎五湖，芙蓉七十夜模糊。","何时一问龙威洞，玉柱金庭事有无。"]},{"t":"春日书室","f":"七言律诗","c":["绿阴绕屋是垂杨，石砌无尘草木芳。","花压床前留蝶梦，叶深檐底出莺簧。","透窗天影涵虚白，落笔风声入硬黄。","细雨初晴云断续，一钩新月映方塘。"]},{"t":"题桃柳鸣禽图","f":"七言绝句","c":["珊珊翠叶淩风绿，袅袅红葩过雨鲜。","一片轻阴晴正好，春声斗碎夕阳天。"]},{"t":"月季花","f":"七言绝句","c":["猗猗叶自淩冬绿，艳艳花常逐月红。","桃颊柳眉休浪妒，芳心原不斗春风。"]},{"t":"雨晴","f":"七言绝句","c":["一夜檐前滴沥声，好风吹作晓来晴。","山头叆叇云犹湿，溪上潺湲水乍生。"]},{"t":"忆二陆故居","f":"七言绝句","c":["九峰空翠碧天横，三泖秋波接汉清。","半夜霜风闻唳鹤，月明飞过五茸城。"]},{"t":"忆戴叔伦墓","f":"七言绝句","c":["七里桥边晓放船，三茅峰色翠连天。","夜台坊下浇杯酒，一束生刍拜昔贤。"]},{"t":"忆莫釐峰","f":"七言绝句","c":["莫釐峰上倚朱阑，七十芙蓉照水寒。","欲向鸱夷问西子，烟波无语绿迷漫。"]},{"t":"忆黄浦江","f":"七言绝句","c":["未必春申有怒魂，江豚吹浪拍云昏。","天留三户亡秦族，莫向方城怨李园。"]},{"t":"忆虞山","f":"七言绝句","c":["言林虞墓树参天，蔓草荒邱古圣贤。","一点浮云在何处，空馀抔土锁凉烟。"]},{"t":"秋夜有感","f":"七言律诗","c":["剪烛无瞑不自聊，惊时感事正萧条。","频年多病游踪少，万里怀人别梦遥。","细雨凉云秋漠漠，清钟疏柝夜迢迢。","愁心几许谁相问，赖有微吟破寂寥。"]},{"t":"夜坐偶吟","f":"七言律诗","c":["心境时光俱黯然，烧残银烛悄无眠。","月沈庭树埋清影，风度茶炉散冷烟。","往事几经回短梦，旧愁仍逐入新年。","凭谁为我销尘念，忽听疏钟落枕前。"]},{"t":"忆涵碧亭柳漫吟","f":"七言绝句","c":["南国烟花满地飞，辽东二月少青丝。","不知涵碧亭前柳，近日东风绿向谁。"]},{"t":"春日忆成翁宝林","f":"五言律诗","c":["茆屋倚青嶂，山窗锁翠岚。","东风吹柳醒，夜雨醉花酣。","仙里谁归鹤，尘缘自缚蚕。","何时一斗酒，相共剖黄柑。"]},{"t":"春夕独眺","f":"七言绝句","c":["独依高楼望海天，迷离晚树锁春烟。","东风吹醒江南梦，花鸟溪山二十年。"]},{"t":"图仕女晓绣因题","f":"七言绝句","c":["梁燕声催晓梦回，新妆绣幕宝奁开。","閒将花鸟收针谱，春色都归指上来。"]},{"t":"偶吟","f":"七言绝句","c":["叶不盈筐觅远枝，瓣香烟绕马头祠。","春蚕自缚缘何事，只向人间作茧丝。"]},{"t":"行山中感吟","f":"五言绝句","c":["空谷寂无声，春风从东来。","伊人在何处，山花空自开。"]},{"t":"山行","f":"七言绝句","c":["断云零落初收雨，满林野鸟閒关语。","空谷山花处处开，不知香气来何许。"]},{"t":"山中","f":"七言绝句","c":["携筇独自入云岩，平野烟低落日衔。","习习东风起空谷，吹将岚气染春衫。"]},{"t":"观表忠观碑","f":"七言绝句","c":["保乂雄威著海涯，丰碑犹自锁烟霞。","不知西子湖边树，可似当年陌上花。"]},{"t":"春词","f":"五言绝句","c":["东风吹落花，落花逐风去。","可怜一片红，飘零竟何处。"]},{"t":"夏日","f":"七言绝句","c":["小院无人夏昼清，芭蕉夜放午阴轻。","绿窗雨过端溪润，好写黄庭傍晚晴。"]},{"t":"即事","f":"七言绝句","c":["窗前晓日下回廊，梦得新诗醒后忘。","槐火石泉真绝响，坡公原住白云乡。"]},{"t":"漫成","f":"古风","c":["永昼闭关无事，小轩插架有书。","北牖清凉乃尔，羲皇世界何如。"]},{"t":"斋中夜坐 其一","f":"古风","c":["帘前花影树影，窗外天光水光。","正喜小炉茶熟，忽闻隔舍酒香。"]},{"t":"斋中夜坐 其二","f":"古风","c":["明月自来自去，好风可东可西。","纸帐乍回残梦，时有幽禽夜啼。"]},{"t":"小圃","f":"五言律诗","c":["小圃足徜徉，虚斋绕绿杨。","课诗消永日，纳爽对斜阳。","径草侵阶暗，庭花拂砚香。","有谁能共赏，独自倚匡床。"]},{"t":"夏昼 其一","f":"七言绝句","c":["绿树垂垂覆草堂，隔帘花气袭人香。","吟馀高卧天怀静，半榻清风午梦长。"]},{"t":"夏昼 其二","f":"七言绝句","c":["柳覆浓阴日正长，拂檐烟缕午风凉。","更无人事来相扰，不独忘言并自忘。"]},{"t":"闻笛","f":"五言律诗","c":["何处吹长笛，高楼正月明。","梅花飞片片，杨柳绿盈盈。","万里凄凉影，三年离别情。","曲终人寂寂，独立忆江城。"]},{"t":"过双峰寺","f":"五言律诗","c":["万壑千峰里，鞭丝独往还。","荒烟迷野径，落叶满空山。","石塔青松掩，柴门碧水环。","老僧无个事，镇日闭禅关。"]},{"t":"题画","f":"七言绝句","c":["渺渺澄波万顷烟，涵空一碧接长天。","月明如雪篷窗冷，谁放山阴半夜船。"]},{"t":"风定晚波平云去秋空净应有息机人独契林泉性","f":"五言绝句","c":["雪冻山上云，雪埋山下路。","空山寂无人，寻梅在何处。"]},{"t":"春夜闻笛因忆江南社友","f":"七言律诗","c":["擪笛何人对月明，东风吹起旧心情。","当年按曲思乡井，此日闻声忆友生。","梅正开时诗共咏，柳经折后岁频更。","欲从梦里寻南国，调急音凄梦不成。"]},{"t":"观儿童春戏感成长句","f":"七言律诗","c":["荏苒韶光每自惊，何堪重忆幼时情。","纸鸢线弱东风软，竹马镫红夜月明。","惟我驽骀劳策励，有人霄汉逞飞鸣。","吴山楚水归来晚，岁月销磨太瘦生。"]},{"t":"晓霁郊行","f":"五言律诗","c":["新晴寒气峭，晨色上巾车。","霁雪迎残月，明霞度晓鸦。","山溪初解冻，野草未生芽。","为忆江南路，东风到处花。"]},{"t":"题桃花双燕图","f":"七言绝句","c":["飞出乌衣王谢家，翻空掠地一双斜。","雪销冰泮芹泥滑，莫逐东风觅落花。"]},{"t":"春日有忆江南诸友戏成回文","f":"七言律诗","c":["东楼小饮共魂销，事往伤心寸念遥。","红日晓迎花萼吐，绿烟晴带柳丝飘。","风帘度燕双来往，月沼惊鱼小动摇。","通梦有人无纸寄，空山晚路远迢迢。"]},{"t":"检点旧文漫占 其一","f":"七言绝句","c":["凌云志气昔如何，暑日寒宵费揣摩。","一自归来不相见，缄函已是十年多。"]},{"t":"检点旧文漫占 其二","f":"七言绝句","c":["编残简断暗尘封，话到丹铅梦亦慵。","早识蠹鱼今日饱，何如买犊学为农。"]},{"t":"雨晴夜坐漫吟","f":"七言律诗","c":["断云无力霭轻阴，暮雨新晴洗俗襟。","柳媚花柔春渐暖，月明风净夜初深。","半生陈迹回魂梦，数卷残书足古今。","安得及时求乐事，閒寻山水遂吾心。"]},{"t":"喜晴","f":"七言律诗","c":["雨霁霞明作晚晴，天公有意慰舆情。","霜场未卜千仓满，云稼堪徵二麦成。","碧垄苗低翻浪细，绿杨叶小簇阴轻。","村翁共话柴扉外，笑指天西气已清。"]},{"t":"山行即事","f":"五言律诗","c":["烟景迎骄马，晴光入望中。","万峰生晓翠，远树乱春红。","鱼跃桃花水，莺啼柳絮风。","云山缘尚浅，空羡草堂翁。"]},{"t":"寺中值雨 其一","f":"七言绝句","c":["萧然古寺万峰围，漠漠青云压翠微。","应是山灵知好客，一天春雨乱红飞。"]},{"t":"寺中值雨 其二","f":"七言绝句","c":["青峰深锁雨濛濛，万木低垂不起风。","莫道山窗太岑寂，此身喜在绿云中。"]},{"t":"晓晴登辉山绝顶 其一","f":"七言绝句","c":["一夜东风雨意阑，朝来馀气作轻寒。","山灵招我登峰顶，欲赠云英作晓餐。"]},{"t":"晓晴登辉山绝顶 其二","f":"七言绝句","c":["直到千峰最上头，白云满地作波流。","远山数角浮烟海，我欲凭风到十洲。"]},{"t":"晓晴登辉山绝顶 其三","f":"七言绝句","c":["凌空怪石竞嵯峨，举首青天近几多。","足下白云乘不得，身无仙骨待如何。"]},{"t":"晓晴登辉山绝顶 其四","f":"七言绝句","c":["零落林花万绿肥，青光相间瀑泉飞。","仆夫劝我下山去，几度支筇未忍归。"]},{"t":"归自辉山途间漫成","f":"七言律诗","c":["草垂山径柳垂堤，朝霭凝烟望眼迷。","树树杏花红雨乱，村村麦陇绿云低。","溪深野涨浮桥面，岸夹新泥没马蹄。","回首琳宫何处是，行人已隔万山西。"]},{"t":"石花","f":"五言古诗","c":["石上有碧草，乃在山之巅。","稽名曰不死，食之延永年。","奈何一小草，便可期神仙。","盖云甘澹泊，本真或能全。","我采不为此，谓其无俗缘。","受气与天清，托根与石坚。","是真契道者，珍重莫轻捐。"]},{"t":"晓晴","f":"七言律诗","c":["碧云吹散夜来风，檐雀声喧晓日红。","烟重柳腰眠不起，雨含花颊醉初融。","半生踪迹尘埃里，七载交游梦寐中。","往事那堪重省忆，晴空望眼送飞鸿。"]},{"t":"题画","f":"七言绝句","c":["芳草萋萋迷远树，苍波渺渺流何处。","扁舟向夕访良朋，篷窗远载残阳去。"]},{"t":"独坐漫吟","f":"七言律诗","c":["小亭半面绕芳池，日永窗移树影迟。","花带馀香归燕垒，絮飞零粉上蛛丝。","眼前物象心生幻，閒里天机静自知。","不觉吟高惊宿鸟，一声幽韵出深枝。"]},{"t":"万泉河纳凉 其一","f":"五言绝句","c":["水阔添新涨，沙平散晚烟。","断云拖雨去，明月正当天。"]},{"t":"万泉河纳凉 其二","f":"五言绝句","c":["河上雨初过，风微起细波。","徜徉不归去，为爱晚凉多。"]},{"t":"立秋前一日暑甚因步水上见时景已有秋意","f":"五言律诗","c":["避炎无处所，为逐水边过。","莲萼飘红粉，蘋花乱白波。","只知秋已近，恰畏暑偏多。","微咏清商曲，临流望素河。"]},{"t":"浑河","f":"七言律诗","c":["浊流直拟下昆崙，襟带陪都众水尊。","捲地东来山作障，排空西去海为门。","声摧雪浪惊雷起，势压风湍阵马奔。","多少黄沙埋白骨，谁凭杯酒吊英魂。"]},{"t":"小亭纳凉","f":"七言绝句","c":["小亭如掌四窗空，帘捲玲珑面面风。","曲沼流将何处去，绿杨深影小桥红。"]},{"t":"小亭值雨","f":"七言绝句","c":["烟垂树影迷深院，雨暗云光压短檐。","忽见四窗天色黑，一齐拖下水晶帘。"]},{"t":"静亭再从兄见有蜾蠃负螟蛉者为他蠃所夺此蠃飞鸣弃去似有所憾赋五古一首见示因和二章奉答","f":"楚辞体","c":["螟蛉寄桑上，有蠃遥负归。","他蠃夺之去，此蠃乃高飞。","鼓翼有怨声，其声一何悲。","蠃兮子勿悲，其故子未思。","见夺因枝远，胡不谋近枝。","蠃兮子勿悲，负子将何为。","此语似不情，此意深可思。","不见梁间燕，待饲常呢呢。","一朝羽翼成，高举无归时。","又不见雏鸡，逐群随伏雌。","爪距少健强，相对生睚眦。","二者非假借，情态犹参差。","有子苟不肖，不如竟无之。","慈乌天性少，反哺安可期。","蠃兮子勿悲，负子将何为。"]},{"t":"晚步","f":"七言律诗","c":["落叶萧萧日影西，青霞光断暮天齐。","平林风紧鸦声乱，野岸云寒雁阵低。","人渡前溪秋水阔，我思远眺晚烟迷。","长歌一曲凭谁和，手画滩沙独自题。"]},{"t":"夜行","f":"五言律诗","c":["车马秋萧瑟，征途夜可怜。","月光澄爽气，山影隔凉烟。","明灭渔村火，横斜野渡船。","远天空极目，箕斗落峰前。"]},{"t":"感吟","f":"七言绝句","c":["三径归来未就荒，篱花砌草自芬芳。","往年十丈红尘里，空逐车轮马足忙。"]},{"t":"夜坐","f":"五言律诗","c":["坐久群嚣息，微吟夜已央。","閒心常自照，虚室暗生光。","凉月明逾静，秋花淡转香。","此时谁共语，帘影上书床。"]},{"t":"种花 其一","f":"七言绝句","c":["引入开渠学种花，欲从园叟伴烟霞。","何时瓮茧成仙骑，骑向璿宫问岁华。"]},{"t":"种花 其二","f":"七言绝句","c":["久甘抱瓮到如今，已见繁枝结绿阴。","有客何来矜技巧，教人机事启机心。"]},{"t":"溪上","f":"五言绝句","c":["何处桃源洞，重来路已迷。","飘飘花片落，流过小桥溪。"]},{"t":"漫吟","f":"七言绝句","c":["几番风信急相催，红雨纷纷点翠苔。","最是轻盈杨柳絮，等閒飞过短墙来。"]},{"t":"春暮","f":"五言律诗","c":["春事馀多少，凄其感物华。","连绵三日雨，零落半帘花。","绿树繁阴重，高楼夕照斜。","怀人归未得，芳草满天涯。"]},{"t":"登辉山","f":"七言律诗","c":["危峰绝顶独盘桓，雾敛云收眼界宽。","千涧瀑兼青霭落，万山岚向碧空攒。","天风欲鼓春衫破，雨气犹侵石骨寒。","何日凌虚生羽翼，十洲三岛足游观。"]},{"t":"过双峰寺","f":"七言绝句","c":["空山雨歇断云低，芳草芊绵石径迷。","古殿无人门自掩，檐铃不语野禽啼。"]},{"t":"云","f":"七言绝句","c":["一片浓云叆叇光，因风舒捲为谁忙。","如何不作知时雨，只解漫空掩太阳。"]},{"t":"忆旧 其一","f":"七言绝句","c":["海门风急浪掀天，一叶舟从铁瓮还。","回首壮游成往事，只馀清梦尚缠绵。"]},{"t":"忆旧 其二","f":"七言绝句","c":["酒兵无计破愁魔，镫火篷窗莫奈何。","明月一天秋水阔，不堪复听唱吴歌。"]},{"t":"忆旧 其三","f":"七言绝句","c":["孤舟曾系古淮阴，漂母祠前万古心。","一种深情在知己，当年原不重黄金。"]},{"t":"忆旧 其四","f":"七言绝句","c":["从来歌吹说维扬，我念琼花不再芳。","今夜窗前看明月，却疑明月是雷塘。"]},{"t":"忆旧 其五","f":"七言绝句","c":["消夏湾头碧水流，西施已泛五湖舟。","试看今日苏台柳，眉黛空含万古愁。"]},{"t":"忆旧 其六","f":"七言绝句","c":["满眼岚光碧四围，荒衙昼静掩芦扉。","多情最是山桃树，一片春红艳不飞。"]},{"t":"忆旧 其七","f":"七言绝句","c":["当日雄谈四座欢，只今独对一镫寒。","可怜十六年中事，尽作流云逝水看。"]},{"t":"忆旧 其八","f":"七言绝句","c":["惭愧巴人只自吟，敢云白雪少知音。","笑伊彭泽真多事，不设冰弦却蓄琴。"]},{"t":"题兰贺人","f":"七言绝句","c":["一丛碧玉净无瑕，有梦徵兰绕绛纱。","应是畹香能解语，双双开作并头花。"]},{"t":"题潇湘图","f":"七言绝句","c":["篷窗镫火夜维舟，天水涵虚静不流。","欲吊湘君何处是，几竿斑竹一湖秋。"]},{"t":"吴文老以诗见示次韵奉答","f":"七言律诗","c":["当年踪迹逐飘萍，空羡吴山处处青。","师友半从愁里别，莺花都似梦中经。","君真佳句追王孟，我亦深情念鹡鸰。","自是文章本天性，此心私幸有仪型。"]},{"t":"冬夜兼怀舍弟","f":"七言律诗","c":["帘外萧萧半夜风，钟声吹入寂寥中。","寒窗纸薄霜威重，老木枝疏月影空。","坐久忽看虚壁白，更阑独对短檠红。","遥怜弱弟三千里，耿耿离愁有梦通。"]},{"t":"过辽阳","f":"七言绝句","c":["东梁河水自西流，漠漠凉烟隐戍楼。","我欲停骖问华表，夕阳城郭锁凉秋。"]},{"t":"过首山","f":"七言绝句","c":["故垒遗踪不可寻，荒原何处大星沈。","迢迢晋魏浮云尽，剩有青山自古今。"]},{"t":"暮过浑河","f":"七言律诗","c":["白草荒芦秋色凄，长河光浸暮云低。","凉波喷雪风声急，古木含烟日影迷。","隔浦人家空寂寂，绕塍禾黍尚萋萋。","一鞭遥指残阳路，不计归程信马蹄。"]},{"t":"有怀 其一","f":"七言绝句","c":["离索劳人太瘦生，不堪重忆旧心情。","吟馀独向东轩立，翘首天涯看晚情。"]},{"t":"有怀 其二","f":"七言绝句","c":["何时樽酒逐欢场，楚水吴山道路长。","我有愁心谁共语，一天黄叶下残阳。"]},{"t":"游观中值雨 其一","f":"七言绝句","c":["杰阁凌虚宝扇开，槐阴松影满楼台。","一声龙笛西风起，四面烟云暮雨来。"]},{"t":"游观中值雨 其二","f":"七言绝句","c":["隐隐雷声走碧空，云收雨霁见长虹。","丹台紫府开仙境，尽在残阳返照中。"]},{"t":"游观中值雨 其三","f":"七言绝句","c":["上方殿宇倚崔嵬，帘捲秋云列岫开。","万木低垂新雨后，一天空翠入窗来。"]},{"t":"游观中值雨 其四","f":"七言绝句","c":["断云拖雨度高空，丹吐霞光剑吐虹。","风定波平天宇净，分明新月在池中。"]},{"t":"连雨暮晴次唐友梅韵","f":"七言律诗","c":["幽窗几日苦凄迷，霁色初开日影西。","云蚀长虹当户断，烟拖残雨拂檐低。","平池积水侵芳草，小径閒花点绿泥。","好待东山明月上，共携短杖听前溪。"]},{"t":"叠前韵","f":"七言律诗","c":["檐溜声中晓梦迷，青虹忽见远林西。","残云翳日花光淡，宿雨凝烟树影低。","素壁行蜗新有篆，绿阶生藓净无泥。","奚童为报山泉长，旧筑渔矶没入溪。"]},{"t":"再叠前韵","f":"七言律诗","c":["共指遥山翠影迷，雷声隐隐乱峰西。","天心忽见云光薄，村外犹看雨脚低。","豹隐已成三日雾，蛇封未辨一丸泥。","门前新涨波澜阔，不是前时没胫溪。"]},{"t":"雨晴同松坡步月河上","f":"七言律诗","c":["急雨初收暑气清，寺门新涨碧痕生。","半规素月潭心落，中夜潜龙梦里惊。","细藻纵横迷树影，微风披拂起波声。","老僧已入维摩定，一任禅镫暗复明。"]},{"t":"红蕉","f":"七言律诗","c":["宵来点点雨声清，朝吐丹葩映日晴。","笑靥半开应解语，芳心未展尚含情。","乱翻翡翠遮天绿，碎碾珊瑚照夜明。","合写簪花淳化帖，窗前宜得万株生。"]},{"t":"新秋偶吟","f":"七言律诗","c":["大火西流暑渐收，忽惊节物又清秋。","露蝉声咽风生柳，篱豆花开月满楼。","诗卷难传无限事，酒杯能遣几多愁。","忽来数点潇潇雨，一片凉云淡不流。"]},{"t":"偶得寒月挂霜枝之句命童子联之松坡遂成一律余即韵成书怀之作","f":"五言律诗","c":["好梦归何处，佳期叹已迟。","残镫昏纸壁，寒月挂霜枝。","空有三馀志，难酬万里思。","徘徊深夜里，此意更谁知。"]},{"t":"又因明月千家雪树影寒霜月二句松坡成篇余亦足成二律 其一","f":"五言律诗","c":["更深群籁息，寂寂立寒庭。","明月千家雪，疏镫一点星。","天光侵户牖，夜气入虚灵。","小饮休教醉，长令方寸醒。"]},{"t":"又因明月千家雪树影寒霜月二句松坡成篇余亦足成二律 其二","f":"五言律诗","c":["深宵不成寐，卧对一镫红。","树影寒霜月，钟声度晓风。","壮心随日去，愁思入诗中。","岁晚惊心切，长吟百感丛。"]},{"t":"夜深忽闻风雨凄然感赋","f":"七言律诗","c":["小炉馀火荻灰温，云暗萧斋静掩门。","半夜惊风吹梦醒，满窗寒雨逼镫昏。","浊醪力薄难为醉，旧事吟成枉断魂。","日月如流伤晚岁，此身空尔寄乾坤。"]},{"t":"友人索画兰并题","f":"七言绝句","c":["冰根几本护苍苔，风叶参差露蕊开。","岂有国香生笔底，却教仙蝶误飞来。"]},{"t":"书桃花扇传奇后 其一","f":"七言绝句","c":["无愁天子爱繁华，媮取金陵作帝家。","燕子新词听未足，春风已落后庭花。"]},{"t":"书桃花扇传奇后 其二","f":"七言绝句","c":["旧院长桥往事空，青山黄土梦魂中。","南朝多少伤心事，付与桃花扇底风。"]},{"t":"书桃花扇传奇后 其三","f":"七言绝句","c":["杜鹃血泪洒京门，岭上衣冠枉断魂。","滚滚长江何处是，梅花影里月黄昏。"]},{"t":"秋夜怀旧","f":"七言律诗","c":["帘捲空窗四壁虚，金壶乍永夜何如。","滴阶露冷蛩声涩，落叶风飘树影疏。","隍鹿已醒他日梦，塞鸿久断故人书。","起看北斗阑干堕，残月萧条上草庐。"]},{"t":"叶本初同其仲兄济范没于海诗以哭之且慰其长兄济东 其一","f":"七言绝句","c":["浪捲星槎竟不回，海天无地寄吾哀。","他年宿草寻何处，永向鲛宫作夜台。"]},{"t":"叶本初同其仲兄济范没于海诗以哭之且慰其长兄济东 其二","f":"七言绝句","c":["水立云垂海气昏，蓬瀛有召赴龙门。","望洋欲酬樽前酒，万顷烟波锁断魂。"]},{"t":"叶本初同其仲兄济范没于海诗以哭之且慰其长兄济东 其三","f":"七言绝句","c":["仲子温恭最象贤，李君尔雅更韶年。","如何携手骑鲸去，同向三壶證水仙。"]},{"t":"叶本初同其仲兄济范没于海诗以哭之且慰其长兄济东 其四","f":"七言绝句","c":["空对鲸波哭杜鹃，修文已入镜中天。","苍龙宫里回螭驭，知是清宁第几年。"]},{"t":"叶本初同其仲兄济范没于海诗以哭之且慰其长兄济东 其五","f":"七言绝句","c":["一夜霜风断雁群，百年泉壤隔音闻。","凭君且拭伤心泪，极目南天有白云。"]},{"t":"冬夜","f":"七言绝句","c":["半夜风吹小雪残，天空北斗挂阑干。","深宵万籁归岑寂，满地冰花月影寒。"]},{"t":"悼亡绝句 其一","f":"七言绝句","c":["入厨洗手自三朝，病里羹犹手自调。","为报慈帏增早膳，一时疴痛似全消。"]},{"t":"悼亡绝句 其二","f":"七言绝句","c":["双双儿女缀班联，五岁娇娃意最怜。","犹禁芳阶閒斗草，却教拈线绣床前。"]},{"t":"悼亡绝句 其三","f":"七言绝句","c":["倚枕支颐制豆娘，五文弱线烂生光。","不知气比游丝细，反为儿曹续命长。"]},{"t":"悼亡绝句 其四","f":"七言绝句","c":["日沈翘首望云天，一种深情已暗传。","向晓不言畴昔梦，泪花瑩澈枕函边。"]},{"t":"悼亡绝句 其五","f":"七言绝句","c":["雅意相关姊妹行，几回分赠嫁衣裳。","惟存数幅亲花绣，犹自尘封黄竹箱。"]},{"t":"悼亡绝句 其六","f":"七言绝句","c":["帘动惊闻步屧声，宛然独自踏阶行。","推窗不见人何处，风自凄清月自明。"]},{"t":"悼亡绝句 其七","f":"七言绝句","c":["短梦初惊曙色微，半宵言笑是耶非。","为怜弱质愁风露，月黑山深那得归。"]},{"t":"悼亡绝句 其八","f":"七言绝句","c":["孤魂喜得傍尊亲，祖母佳城近比邻。","应倚夜台松柏影，共看明月忆家人。"]},{"t":"悼亡绝句 其九","f":"七言绝句","c":["剩粉零膏手泽新，青箱翠匣锁轻尘。","最怜弱女偏珍惜，不肯开奁付与人。"]},{"t":"游蜂菊花","f":"七言绝句","c":["漫从篱下采黄华，风露凄清且闭衙。","好是春风三二月，莫教孤负上林花。"]},{"t":"晓渡浑河","f":"七言绝句","c":["未动荒鸡夜寂寥，风吹雪浪冷萧萧。","为看沙上青霜迹，已有行人早度桥。"]},{"t":"题画兰","f":"七言绝句","c":["几叶淋漓草带真，有人挥洒诩传神。","何时收取花间露，为我毫端洗俗尘。"]},{"t":"送唐友梅","f":"七言绝句","c":["目断衰杨倚驿桥，天连晴雪正萧萧。","万泉河上重携手，恰待春风碧柳条。"]},{"t":"检张瀛客先生遗诗 其一","f":"七言绝句","c":["断简离披剩一编，最怜窥豹未能全。","白云化去缑山鹤，春露秋霜二十年。"]},{"t":"检张瀛客先生遗诗 其二","f":"七言绝句","c":["几树松楸锁夕阳，谁题诗伯夜台坊。","云山有梦三千里，便是生离也断肠。"]},{"t":"游仙 其一","f":"七言绝句","c":["瑶草琪花绕玉台，昆崙绝顶四天开。","林间空有三青鸟，八骏东归不再来。"]},{"t":"游仙 其二","f":"七言绝句","c":["碧海青天一剑孤，归来独倚旧丹炉。","故山风月栖迟好，不看巾箱五岳图。"]},{"t":"晴望","f":"七言绝句","c":["万峰流翠雨初晴，泽被郊原草木荣。","蜡屐最高山上望，麦苗千顷绿云平。"]},{"t":"村中","f":"七言绝句","c":["数椽茅屋自成村，半带残阳半掩门。","烟柳低眠风不起，暮鸦声里月黄昏。"]},{"t":"沽酒","f":"五言律诗","c":["家酿瓶之罄，来沽小市前。","君谋花下醉，我解杖头钱。","不惜杯三百，何妨斗十千。","杏林春正好，共酌酒旗边。"]},{"t":"春郊即事","f":"七言律诗","c":["芳原土润绝纤埃，款段霜蹄踏碧苔。","晓雾犹笼杨柳重，初暾欲炽杏花开。","桑林雨霁鸠呼妇，麦垄朝和雉引媒。","剪剪春寒风力薄，旗亭驻马暂衔杯。"]},{"t":"答阎古樵和韵","f":"七言律诗","c":["望中霁色绝嚣埃，蜡屐冲泥印软苔。","烟烧平林青霭合，天排远岫画屏开。","金莺出谷相求友，玉蝶寻芳互引媒。","何日东皋同载酒，与君拈韵共传杯。"]},{"t":"同黎悦安阎古樵弈棋夜饮","f":"七言律诗","c":["风吹清漏夜漫漫，把酒敲棋兴未阑。","乐事抵须千日醉，浮生转瞬半枰残。","功名尘土成蕉梦，松柏冰霜结岁寒。","聊取欢颜忘胜负，倾怀莫放一杯宽。"]},{"t":"再出东郊","f":"五言律诗","c":["芳园归几日，重适野人家。","树树闻山鸟，村村见杏花。","溪痕新涨雨，草色渐藏沙。","依旧东皋路，旋看易物华。"]},{"t":"唐友梅病中寄诗一律次韵奉覆","f":"七言律诗","c":["四年笔砚共相依，几向丹铅覈是非。","尘榻无人联夜雨，沂风独自咏春衣。","心怜药饵愁多病，目断云山锁落晖。","闻道蒲觞新有约，为藏佳酿待君归。"]},{"t":"柳絮","f":"七言绝句","c":["几株碧柳小窗东，弱线低垂度晓风。","似解催人吟白雪，飘来数点砚池中。"]},{"t":"清明","f":"七言绝句","c":["墓柳青青墓草黄，一盂麦饮奠椒浆。","可怜无限伤心泪，洒向东风血数行。"]},{"t":"雨后独步小园","f":"五言律诗","c":["漠漠轻阴合，孤吟小苑中。","断云拖细雨，高树起微风。","草入平池绿，花飞曲径红。","徘徊对轩槛，幽兴倩谁同。"]},{"t":"榆钱","f":"七言绝句","c":["欲买春风是也非，枝头乱挂五铢微。","凭将柳线轻穿缀，莫逐杨花作雪花。"]},{"t":"月映万川 其一","f":"七言绝句","c":["清光照破九州烟，万派澄鲜一影圆。","滟滟金波涵静体，不随逝水下长川。"]},{"t":"月映万川 其二","f":"七言绝句","c":["素魄高悬出海天，飞来万影入澄川。","自然妙用皆无意，水自空明月自圆。"]},{"t":"恭谒曾祖朝议公墓","f":"五言律诗","c":["水绕柴河堡，山开一面城。","银冈分脉结，金体众峰呈。","泽衍衣冠冑，心悲风木声。","十年期展拜，此日遂乌情。"]},{"t":"铁岭东山道中","f":"五言律诗","c":["山谷绕奇胜，清幽慰旅行。","云从车下起，田向树头耕。","石栈低天影，烟林出水声。","卜居知未遂，吟望有馀情。"]},{"t":"恭谒高祖武翼公墓","f":"五言律诗","c":["佳城临塞地，郁郁近边垠。","云气滋灵草，山君守墓门。","千年开吉兆，五叶拜元孙。","惭愧承先德，瞻依欲断魂。"]},{"t":"清河道中","f":"七言律诗","c":["万山环合翠岚浮，策马斜阳古挹楼。","峰辟关门天一线，浪翻峡口水双流。","寒烟漠漠村墟暮，野港萧萧芦荻秋。","回望凤城何处是，西南翘首白云头。"]},{"t":"绿牡丹","f":"七言绝句","c":["东风拂槛一枝春，移赠秋芳号转真。","能傲严霜贞晚节，前身合是堕楼人。"]},{"t":"粉红莲","f":"七言绝句","c":["亭亭独立对西风，不比凌波坠粉红。","莫道莲花最高洁，清香合与晚香同。"]},{"t":"万花魁","f":"七言绝句","c":["共道梅花万卉魁，秋魁篱菊胜江梅。","如何烂漫西风里，不向群芳顶上开。"]},{"t":"满天星","f":"七言绝句","c":["霜天月黑倍昭然，分野从来应地躔。","不是寒香侵座右，几疑星斗落阶前。"]},{"t":"邓州黄","f":"七言绝句","c":["金蕊初开玉露凉，百花洲上点秋光。","范公遗谱知多少，应共香橙一色黄。"]},{"t":"洋红","f":"七言绝句","c":["谁碾朱砂拥菊丛，丹葩和露绽西风。","一从番舶来中土，赢得扶桑晓日红。"]},{"t":"粉针","f":"七言绝句","c":["移得秋英傍绣床，鸳鸯剌罢理残妆。","误将腻粉黏针线，挑出花心瓣瓣长。"]},{"t":"镜中菊影 其一","f":"七言绝句","c":["谁移篱菊近妆台，高捲珠帘宝扇开。","瘦影尽教归朗照，秋光收入座中来。"]},{"t":"镜中菊影 其二","f":"七言绝句","c":["不让金波灿夜华，清光澄澈映寒葩。","暂移月里中秋桂，添得霜前九日花。"]},{"t":"镜中菊影 其三","f":"七言绝句","c":["几枝错落秋花影，一片虚明玉镜光。","纵使鉴形能取象，空教写照不分香。"]},{"t":"镜中菊影 其四","f":"七言绝句","c":["花临宝镜空非色，镜锁秋英色未空。","真假尽缘心作幻，倩谁勘破有无中。"]},{"t":"镫下菊影 其一","f":"七言绝句","c":["移将篱菊避霜风，掩映萧斋烛爓红。","瘦影不须秋水照，清标收入素屏中。"]},{"t":"镫下菊影 其二","f":"七言绝句","c":["轩窗深锁绝风尘，菊对秋镫影倍真。","最是一枝斜更好，何人泼墨为传神。"]},{"t":"镫下菊影 其三","f":"七言绝句","c":["最怜镫下影偏幽，一榻寒香四壁秋。","欲写芳标留玉版，聊将斑管学双钩。"]},{"t":"镫下菊影 其四","f":"七言绝句","c":["秋英争向纸屏开，水月空花惹浪猜。","已悟无生庄叟意，有形都自幻中来。"]},{"t":"忆送别唐友梅","f":"五言律诗","c":["忆昔离亭日，骊歌酒半阑。","乾坤双鬓冷，风雪一身单。","羸马关山远，长途岁月残。","谁知成死别，吟望泪阑干。"]},{"t":"樵径","f":"七言绝句","c":["踏破苍苔古木阴，腰斤日日入幽岑。","几多城市炊烟处，荷担谁怜径路深。"]},{"t":"樽酒慰离颜","f":"五言律诗","c":["预拟倾尊酒，相期客子还。","休忘他日醉，记取去时颜。","萍水踪难定，风霜鬓莫斑。","何年成慰藉，痛饮对刀环。"]},{"t":"刘守愚先生自海上得奇石因纪古风八韵余既次和未尽所言复为长歌","f":"七言古诗","c":["混沌既凿开㟏岈，不周山倒愁女娲。","伟绩奏成馀残块，棋布山巅或水涯。","闾山趾有补天石，此石眷属应一家。","谁知沦落在海澨，沐日浴月葆精华。","天风海涛作知己，藉以芳草见烟霞。","天生灵物岂终隐，不使万古埋泥沙。","我有父执刘守愚，读书博物为通儒。","暂去司铎驻锦水，遂以捧檄勘海隅。","平生好奇惯搜剔，披检荆棘穷崎岖。","忽得此石拜且舞，呼兄呼丈载以车。","古苔斑剥土花润，鹧鸪点閒龙文纡。","秦皇鞭迹殷馀血，望夫粉黛娇模糊。","形质兼备瘦皱透，上皇山石恐不如。","忆昔汗漫杭一苇，半在吴头半楚尾。","金焦北固峙海门，烛目怪石比比是。","猛兽奇鬼相攫拿，片云孤帆欲飞起。","泗滨石磬设堂皇，灵壁砚山置棐几。","少年弃掷不知惜，念言回首徒然耳。","今读君诗忽神王，赓以短章意未畅。","更因海峤忆经游，廿年尘迹空惆怅。","羡君得石良足多，神毫濡墨为长歌。","胸无灵珠吻复拙，石乎石乎当奈何。"]},{"t":"宿塔湾","f":"七言绝句","c":["倚枕挑镫梦不成，寒鸡啼月夜三更。","思亲怀友情多少，才是消魂第一程。"]},{"t":"医无闾山","f":"五言律诗","c":["幽并开巨镇，封置自尧年。","雄气平吞海，危峰欲柱天。","雪凝流冷翠，岚重带晴烟。","未遂登临愿，停骖吊昔贤。"]},{"t":"宿雄县","f":"七言绝句","c":["易水萧萧白日凉，飞桥十二断虹长。","思亲一夜关山梦，半在淮阳半沈阳。"]},{"t":"过易水","f":"七言绝句","c":["一剑寻仇计本疏，空将督亢入秦都。","于期刎颈田光死，不信荆卿不丈夫。"]},{"t":"臧家桥","f":"七言绝句","c":["淡烟轻雾锁长河，寒水流澌不起波。","晓色离离乡梦醒，风吹残月渡滹沱。"]},{"t":"过德州","f":"七言绝句","c":["雅雨天才本擅场，一肩风月继渔洋。","如何不悟焚身祸，有客停车泪满裳。"]},{"t":"平原吊颜鲁公 其一","f":"七言绝句","c":["扑面风沙欲断魂，驱车独出古平原。","鲁公祠宇知何处，衰草连天日影昏。"]},{"t":"平原吊颜鲁公 其二","f":"七言绝句","c":["不愧先贤不愧儒，更将馀技妙操觚。","几多蔓草荒烟里，金石遗文尚有无。"]},{"t":"过齐长城","f":"七言绝句","c":["绵亘山川一带长，萧条断垒锁残阳。","已经作俑开秦祸，空使千秋罪始皇。"]},{"t":"梦洪大亮吉忆旧时同出此途感吟二首 其一","f":"七言绝句","c":["故人旌节驻黔中，十八年来事不同。","今日重行黄叶路，愁人依旧白杨风。"]},{"t":"梦洪大亮吉忆旧时同出此途感吟二首 其二","f":"七言绝句","c":["万里何缘入梦中，照人颜色旧时同。","醒来不是当年事，寒气侵衣起朔风。"]},{"t":"诸葛武侯故里","f":"七言绝句","c":["大书深刻著荣名，灭魏吞吴恨未成。","沂水萧萧愁不断，我来何处拜先生。"]},{"t":"过宿迁感怀二首 其一","f":"七言绝句","c":["河上重经感昔时，伤心世事一人知。","先生久赴琼楼召，尚有遗民颂口碑。"]},{"t":"过宿迁感怀二首 其二","f":"七言绝句","c":["五载香销痛别鸾，墓门草断碧烟寒。","不知同在重泉下，可是人间见面难。"]},{"t":"夜晴","f":"七言绝句","c":["濛濛如雾复如烟，滴沥声中夜不眠。","忽被北风收拾去，碧空云净月当天。"]},{"t":"舣舟亭","f":"七言绝句","c":["此地曾经访大苏，舣舟亭下夜舟孤。","重来哽咽髫年事，不为重慈作杖扶。"]},{"t":"梅","f":"五言绝句","c":["自挟冰霜气，何须珠玉词。","水边篱落后，无复擅场诗。"]},{"t":"甓社湖感怀","f":"七言律诗","c":["片帆曾挂甓湖烟，五两风轻荡画船。","负笈有书空饱蠹，垂云无翼可摩天。","相如近日常多病，叔宝当时最少年。","细认遗踪何处是，半篙春水绿依然。"]},{"t":"镜中梅次张力庵韵","f":"七言律诗","c":["馀雪侵窗独闭门，盆梅奁镜对黄昏。","十分皎洁涵清照，一片虚灵浸冷魂。","姑射琼姿奔月窟，汉妃珠影落江村。","传神已是含全像，莫认残妆半面痕。"]},{"t":"登高邮西城楼","f":"七言律诗","c":["缥缈春波接远天，高楼长眺独萧然。","依依树影留残月，点点村炊上晚烟。","此地维舟廿九载，当时垂发十三年。","东风依旧吹杨柳，俯仰青衫祇自怜。"]},{"t":"题画","f":"七言绝句","c":["家山好处正依稀，蝴蝶空劳梦里飞。","孤负草堂春树绿，落花啼鸟未曾归。"]},{"t":"秦邮寓中绝句 其一","f":"七言绝句","c":["红破榴花日正长，北窗风至作微凉。","翩翩燕子来何处，知啄香泥绕旧梁。"]},{"t":"秦邮寓中绝句 其二","f":"七言绝句","c":["难将好梦慰乡情，卧暖桃笙梦不成。","何处兰舟双画橹，咿呀声里客魂惊。"]},{"t":"秦邮寓中绝句 其三","f":"七言绝句","c":["翘首西楼月又生，蛾眉七度对离情。","不知此夜纤纤影，照到征人第几程。"]},{"t":"题张力庵崇川花谱吟 其一","f":"七言绝句","c":["笔花灿烂墨花香，写出金钗十二行。","蠡卖窗明眠未起，不知晓梦为谁忙。"]},{"t":"题张力庵崇川花谱吟 其二","f":"七言绝句","c":["旧事吟成枉断肠，平生我不诩情长。","东风不管花开落，芳草连天自夕阳。"]},{"t":"登文游台","f":"五言律诗","c":["徙倚高台暮，凭栏忆昔贤。","风流皆绝代，身世正萧然。","虚阁下残照，平湖澄远天。","徘徊未归去，镫火破疏烟。"]},{"t":"露筋祠","f":"五言绝句","c":["祠树集昏鸦，平湖没晚霞。","野风何处起，吹落白莲花。"]},{"t":"夜抵维扬","f":"七言律诗","c":["水映蓬窗夜气凉，邗江古岸泊舟航。","玉箫风静吹明月，粉堞烟深绕绿杨。","跨鹤已成他日梦，寻花非复少年场。","星星萤火沾清露，欲问雷塘事渺茫。"]},{"t":"游平山","f":"五言律诗","c":["维扬称钜丽，今古竞繁华。","绿水飞兰桨，垂杨隐钿车。","绮罗春拾翠，镫火醉评花。","十里平山路，香风处处赊。"]},{"t":"瓜州阻风忆贾丈汉庭 其一","f":"七言绝句","c":["风捲江湖海逆流，弄风蛟蜃上涛头。","篷窗屏息何曾寐，渔火光中一夜愁。"]},{"t":"瓜州阻风忆贾丈汉庭 其二","f":"七言绝句","c":["二十年前访荜门，春风携我锦春园。","只今宿草无人问，何处冬青锁断魂。"]},{"t":"游灵岩山归作","f":"七言绝句","c":["塔挂残阳欲暮天，灵岩支港泛归船。","回头却顾经行处，云际钟声破晚烟。"]},{"t":"黄河待渡值重阳","f":"七言律诗","c":["待济长河古驿旁，舆夫报我是重阳。","人争野渡秋烟冷，目极平沙岸草荒。","小市漫沽村酒薄，颓垣也有菊花香。","长堤谁是登高伴，滚滚洪流望渺茫。"]},{"t":"登岱 其一","f":"七言律诗","c":["奉阴碑左独停骖，身向天关试一探。","峰顶晴光留夕照，城头寒色压秋岚。","登临不为风尘倦，山水从来梦寐眈。","只忆白云亲舍远，回肠东北更东南。"]},{"t":"登岱 其二","f":"七言律诗","c":["岱麓经过忆昔年，跻攀今日秉心虔。","生成功继乾坤后，典礼尊居岳渎先。","鸟道已经离世界，石门犹是倚云天。","杜陵诗句裁零锦，大笔摩崖处处镌。"]},{"t":"登岱 其三","f":"七言律诗","c":["五更沧海吐明蟾，杖策登云过水帘。","辇道旧传排御幛，神坛曾见出金奁。","碑铜蚀雨生苔蕊，瓦铁翻风堕殿檐。","应是最高寒亦重，山人习久不知嫌。"]},{"t":"登岱 其四","f":"七言律诗","c":["作镇青齐控九区，丹梯万级入云衢。","东西日月窥浮没，远近龟蒙效拜趋。","笔力未能摇五岳，目光安敢望三吴。","到来天下真知小，大地苍茫似有无。"]},{"t":"无字碑","f":"七言绝句","c":["仅有丰碑表泰山，更无人迹在人寰。","多缘事出焚书后，不欲文章著世间。"]},{"t":"途中 其一","f":"七言绝句","c":["策马来思雪作花，归途秋色上蒹葭。","应知老母凝眸处，望断征鸿望暮霞。"]},{"t":"途中 其二","f":"七言绝句","c":["欲济无舟可奈何，倚闾宁卜事蹉跎。","不知衣上来时线，可及思儿泪点多。"]},{"t":"途中 其三","f":"七言律诗","c":["踟蹰病马倦西风，扑面尘沙捲断蓬。","岁月销磨魂梦里，心情黯淡别离中。","远山漠漠秋云冷，古木萧萧落照红。","行道无人能缩地，举头天际羡飞鸿。"]},{"t":"都中晤洪稚存即留别 其一","f":"七言绝句","c":["忆别何期十九年，愁肠几度梦魂牵。","谁知意外停征马，恰得京华续旧缘。"]},{"t":"都中晤洪稚存即留别 其二","f":"七言绝句","c":["太液池莲问酒楼，凉风吹柳正新秋。","即今人事升沈异，同是萧萧欲白头。"]},{"t":"都中晤洪稚存即留别 其三","f":"七言绝句","c":["当时妄念未能酬，罔自风尘逐道周。","君有雄文应寿世，我将骥附亦千秋。"]},{"t":"都中晤洪稚存即留别 其四","f":"七言绝句","c":["一尊清酒又骊歌，此后相思更奈何。","海内比邻知己在，天涯万里不嫌多。"]},{"t":"旅邸","f":"七言绝句","c":["黯黯孤檠冷不明，拂衣秣马待鸡声。","无端最是疏林叶，底事萧萧彻夜鸣。"]},{"t":"春日漫成","f":"七言律诗","c":["天际云收日正晴，阶前花映纸窗明。","欲沽春酒榆钱小，为绾东风柳线轻。","坐久忽看移树影，吟高偶觉和禽声。","诗成浑未思工拙，不为閒争旦夕名。"]},{"t":"小亭静坐","f":"七言律诗","c":["艳影香风匝小亭，吟馀书竟对虚屏。","更无人事生烦扰，自有天机见性灵。","瘦绿肥红皆妙道，落花啼鸟共忘形。","爱他止水澄波静，閒倚雕阑望渌渟。"]},{"t":"题画 其一 垂钓图","f":"七言绝句","c":["门对空江水接天，翠屏倒影浸云烟。","一竿风月无人管，閒数沙鸥倚钓船。"]},{"t":"题画 其二 观澜图","f":"七言绝句","c":["涟漪曲曲绕柴门，曳屐携筇验涨痕。","数点桃花落何处，试沿溪水觅来源。"]},{"t":"题画 其三 寻梅图","f":"七言绝句","c":["寻春携侣问烟霞，蜡屐冲泥鸟道斜。","笑指溪边深竹里，东风已绽一枝花。"]},{"t":"题画 其四 钓艇图","f":"七言绝句","c":["万峰攒翠倚晴空，倒影清江碧镜中。","自契天机忘得失，满船明月一竿风。"]},{"t":"题画 其五 携琴图","f":"七言绝句","c":["峰危径僻古亭深，自与幽人契素心。","绝调凭谁同一赏，空山泉石是知音。"]},{"t":"题蛱蝶 其一","f":"七言绝句","c":["几丛芳草径三三，逗引寻香凤子酣。","梦里东风何处是，关心春色在江南。"]},{"t":"题蛱蝶 其二","f":"七言绝句","c":["家园处处好芳菲，合是归时便得归。","纵使江南风日暖，莫随花担过桥飞。"]},{"t":"题蛱蝶 其三","f":"五言绝句","c":["春深花重时，香重花深处。","仙蝶最相怜，飞来不飞去。"]},{"t":"春日","f":"七言律诗","c":["渐觉东风动柳条，小池春水雪初消。","画梁旧垒来新燕，红药枯根茁嫩苗。","细雨侵人寒料峭，醇醪薄醉梦逍遥。","已筹五两冲泥屐，溪友寻芳拟共招。"]},{"t":"春阴","f":"七言绝句","c":["云掩青山影欲无，东风犹自砭肌肤。","谁能为我开生面，写作春寒欲雨图。"]},{"t":"题平湖远眺","f":"七言绝句","c":["澄湖秋老荻花洲，浅水平沙舣钓舟。","忆得秦邮拖蜡屐，西风独上玩珠楼。"]},{"t":"题晚径归樵","f":"七言绝句","c":["一肩归自夕阳边，石磴云岑独往还。","试望前村深树里，谁家犹有未炊烟。"]},{"t":"春行","f":"五言绝句","c":["我正寻春去，春风向我来。","妙香时断续，何处野花开。"]},{"t":"春晴兼忆倪李诸君","f":"七言律诗","c":["云破青霄作午晴，日光乍暖碎禽声。","依依柳线迎风软，点点榆钱落地轻。","芳草迷空春欲暮，绿波隔浦水初平。","故人一别无消息，可向辽东忆此情。"]},{"t":"晚晴 其一","f":"七言绝句","c":["灵鹊呼晴对草堂，半帘树影下残阳。","湿云缓度前溪去，留得轩窗雨气凉。"]},{"t":"晚晴 其二","f":"七言绝句","c":["趁将落日捲西窗，净涤陶泓拓硬黄。","漠漠凉云飞不起，尚拖细雨润书床。"]},{"t":"海棠蛱蝶","f":"七言绝句","c":["露重清秋夜乍凉，古墙阴下点红妆。","怀人欲托相思梦，梦里依然是断肠。"]},{"t":"丽人行","f":"七言古诗","c":["舍北女儿画眉短，秋波澄澈青螺远。","云罗雾縠缟素衣，至今尚未逢刘阮。","舍南女儿画眉长，春山掩映流辉光。","翠羽明珠雕玉佩，至今未嫁东家王。","桃李香飞春色里，芙蓉照影秋江水。","桃李花时芙蓉生，芙蓉花时桃李萎。"]},{"t":"秋日","f":"七言绝句","c":["木叶初飞水乍凉，荻花断岸倚孤航。","蓬窗极目轻云碧，书破秋空雁一行。"]},{"t":"古木寒鸦图","f":"七言绝句","c":["疏林萧瑟已凉天，结阵寒鸦往复还。","落叶风多栖未隐，秋声啼破夕阳烟。"]},{"t":"芦洲独钓图","f":"七言绝句","c":["秋光已到荻花滩，昨夜霜添桕叶丹。","欲问伊人何处是，空江万里一渔竿。"]},{"t":"夜坐漫吟","f":"七言律诗","c":["猎猎西风万籁哀，镫昏残漏梦初回。","明蟾影落轻霜白，黄叶声惊急雨来。","鬓雪不容诗笔扫，愁城暂借酒兵开。","旧游往事都萧索，剩有牛衣卧草莱。"]},{"t":"题落花蝴蝶","f":"七言绝句","c":["东君归去落花中，万点阑珊一夜风。","蛱蝶也知春可惜，共沿溪水觅残红。"]},{"t":"夏日漫成","f":"七言绝句","c":["茅亭窗外放新荷，小沼薰风起细波。","赤日行空浑不识，垂杨满地绿阴多。"]},{"t":"新凉","f":"七言绝句","c":["文窗凉意透红纱，暮雨初收月正斜。","庭院无尘苔色净，雕阑新放紫薇花。"]},{"t":"与长男图箕试助教官箕中式第一余第二奉文行取入都","f":"七言律诗","c":["此身自分卧烟霞，鹤简来催两鬓华。","未必云霄终梦寐，依然笔墨是生涯。","儿曹幸已开前路，老子何妨殿后车。","为祝慈亲休远望，归来綵服拜宫花。"]},{"t":"谒夷齐庙","f":"七言律诗","c":["万壑群峰朔气飞，夷齐祠下暂停騑。","只今北海惭顽懦，终古西山叹蕨薇。","泺水要人瞻圣范，清风为我振行衣。","低徊几度难言去，滚滚寒涛下夕晖。"]},{"t":"新店吊周将军遇吉","f":"七言律诗","c":["天命潜移自正嘉，竖儒窃柄起征沙。","烈宗若遣尊旄钺，逆贼宁惟避纛牙。","万载蒸尝崇我国，一门忠勇属君家。","孤魂莫向西翘首，故主山陵锁暮霞。"]},{"t":"晓行","f":"五言律诗","c":["镫光回短梦，星影照征鞍。","冰雪三冬暮，轮蹄五夜寒。","情深诗语拙，心静酒杯宽。","去日吟题句，今期取次看。"]},{"t":"道中吟 其一","f":"七言绝句","c":["烟光岚色拥榆关，远近群峰耸翠鬟。","任使严风吹短鬓，不教垂幰为看山。"]},{"t":"道中吟 其二","f":"七言绝句","c":["雪光艳艳起寒烟，月落星疏欲曙天。","山影遥开云五色，凤城应在日轮边。"]},{"t":"暮春临帖偶吟","f":"七言绝句","c":["一片轻云细雨过，绿杨院宇落花多。","晴窗写得黄庭帖，愧杀丰神不换鹅。"]},{"t":"题兰","f":"五言绝句","c":["空谷自古今，何忧伍众草。","惠然来清风，幽香在怀抱。"]},{"t":"遐亭以诗见寄次和却寄 其一","f":"七言律诗","c":["挹翠堂前翠若何，睫巢黄叶晚风多。","梦回远道迷秋雨，月落清辉隔绛河。","寸草春晖依爱日，尺书双鲤托洄波。","嗟余离索无同调，羡子埙篪叠奏和。"]},{"t":"遐亭以诗见寄次和却寄 其二","f":"七言律诗","c":["聚首分襟有夙因，云山万叠隔情亲。","莺期未卜同声日，梅信空劳远驿尘。","落叶凉风来旅雁，斜阳秋水望伊人。","余怀渺渺凭谁诉，镜里频添白发新。"]},{"t":"书斋独坐","f":"五言律诗","c":["秋气薄书床，金壶漏乍长。","凉风吹短鬓，明月满虚堂。","木叶飞轻影，篱花送远香。","清宵谁共赏，独自步回廊。"]},{"t":"秋日过双峰寺","f":"五言律诗","c":["小憩双峰寺，峰头挂夕阳。","溪光浮殿宇，岚翠滴衣裳。","漠漠晚天碧，离离秋草黄。","西风送归骑，铃铎听微茫。"]},{"t":"冬初归自东郊","f":"五言律诗","c":["策马残阳里，寒云极目平。","林空霜野阔，水定草桥成。","败叶随风起，澄潭促浪清。","衡门何处是，新月一钩横。"]},{"t":"露兰","f":"七言绝句","c":["冰根碧叶杂荒芜，晓露迎晖缀宝珠。","笑靥半含还半吐，素心皎皎濯醍醐。"]},{"t":"晴兰","f":"七言绝句","c":["谷风吹野养花天，九畹幽丛散暖烟。","仙蕊露乾香远馥，向阳几叶影翩翩。"]},{"t":"月兰","f":"七言绝句","c":["苔护崇兰结绿阴，玉绳不动夜沈沈。","石边几本冰根冷，素魄流辉映素心。"]},{"t":"题画兰","f":"七言律诗","c":["细雨侵窗古砚凉，挥毫兰蕙满书堂。","素屏绕榻占清梦，墨沈临风散祖香。","阆苑有花春百亩，空山结佩楚三湘。","是谁臭味从吾好，入室同心两坐忘。"]},{"t":"雪兰","f":"七言绝句","c":["风促同云捲雪狂，飘来兰畹压幽芳。","素心本具冰霜操，飞向窗前作冷香。"]},{"t":"题破盆兰花","f":"七言绝句","c":["宝墨淋漓染素翰，破盆偶仿板桥兰。","祖香自是无增减，莫与雕栏两样看。"]},{"t":"冬夜怀遐亭 其一","f":"五言律诗","c":["皎皎西飞月，愁心欲寄难。","故人千里隔，树影一庭寒。","诗句凭谁赏，星躔祇独看。","无穷惆怅意，吟望自盘桓。"]},{"t":"冬夜怀遐亭 其二","f":"五言律诗","c":["夙慧钦吾子，天机迥绝伦。","素心盟澹泊，雅度出风尘。","孤夜牵离梦，联吟忆早春。","何时重晤语，剪烛醉芳醇。"]},{"t":"冬日过双峰寺","f":"五言律诗","c":["寒云萦古殿，画壁敞双楹。","积雪透山骨，断冰流水声。","岩枯岚影淡，烟冷暮光清。","策蹇人归去，依依系别情。"]},{"t":"雪","f":"五言律诗","c":["漠漠春云重，飞花撒玉团。","侵来书幌白，铺向草堂宽。","喜卜三农瑞，愁增万井寒。","冷风吹不断，梦里打窗栏。"]},{"t":"雪晴","f":"七言律诗","c":["夜来碎玉已收声，窗纸生红喜得晴。","旭日乍烘春雪艳，东风缓送晓云轻。","童寒扫径频呵手，雀暖争枝互斗鸣。","为忆探梅曾策蹇，璚瑶踏遍觅诗程。"]},{"t":"度岁以来雨雪连绵晴日颇少寒气愈盛因成长律","f":"七言律诗","c":["两月才能几日晴，六花时作打窗声。","冻云不遣东风解，冷絮将填大海平。","积素庭轩常没胫，凝寒草木尚含萌。","围炉呵砚吟扪鼻，兽炭频添酒独倾。"]},{"t":"赠金泗樵","f":"七言律诗","c":["早从洙泗溯渊源，更向图书究本原。","星斗心胸天亦小，缥缃糟粕卷空繁。","诗敲晴雪看文藻，座入春风仰笑言。","樗栎我惭依玉树，愿将绳墨就班门。"]},{"t":"城楼远望","f":"七言律诗","c":["无边景象望中来，城上楼高近帝台。","四塔佛光摩日月，二陵佳气接蓬莱。","山川盘郁风云壮，阡陌纵横锦绣开。","万祀龙兴重根本，天经地纬缅鸿裁。"]},{"t":"郊行","f":"五言律诗","c":["冥冥馀夜气，蒙影现遥天。","白剩幽岩雪，青飞远岫烟。","山岚含叆叇，河水泛沦涟。","渔父知何处，沙鸥傍钓船。"]},{"t":"感吟 其一","f":"古风","c":["未得竟寻丘壑，尚能小有林塘。","不觉半生是梦，居然两鬓如霜。"]},{"t":"感吟 其二","f":"古风","c":["往事已如逝水，旧游都是空花。","莫忆当年幻境，且娱眼下韶华。"]},{"t":"泗樵言秦君梗概不胜悼惜因成长句","f":"七言律诗","c":["先生自是不羁才，湖海飘零亦可哀。","圮上素书当日秘，枕中鸿宝几时开。","飞鸿剑气沈牛斗，明月珠光没草莱。","交臂无缘成怅惘，难将遗恨问泉台。"]},{"t":"次春郊元韵","f":"五言古诗","c":["野游晴正好，款段踏芳春。","绿柳才舒眼，朱樱未点唇。","花光含丽日，风意起青蘋。","远岫凝轻黛，洄波皱细鳞。","韶华呈艳冶，诗句斗鲜新。","应接人无暇，长吟小欠伸。"]},{"t":"次春日六韵","f":"七言古诗","c":["题春佳句属君家，我亦颦眉咏物华。","胸有灵机舒锦绣，天将丽景灿云霞。","绿烟拂地千株柳，红雨飞空十里花。","树底车宜乘小驷，风前扇拟试团纱。","一樽村酿携柑酒，盈把山蔬荐蕨芽。","投得奚囊诗句满，野芳醉插帽沿斜。"]},{"t":"次和夜月观花八韵","f":"七言古诗","c":["寂寂名园笼月地，溶溶皓魄照花天。","寻春无事登山屐，卜夜疑乘棹雪船。","植得瑶池琪树满，涌来碧海宝珠圆。","空涵色象真成幻，写入虚灵艳更妍。","一片金波镕玉镜，万枝紫姹间红嫣。","冰魂漏永迷蝴蝶，芳梦宵深警杜鹃。","皎洁不随云影暗，妖娆正浥露华鲜。","如斯景物君能咏，想像香光我亦怜。"]},{"t":"次和泗樵见赠之作","f":"七言律诗","c":["隽笔曾无一点尘，吟来字字拟南珍。","会心花鸟皆成妙，得意文章信有神。","桃李门墙三月雨，诗书酝酿四时春。","驽骀我久惭追步，君独超群迈等伦。"]},{"t":"金泗樵以多篇见示答以长歌","f":"古风","c":["火轮飞燄天中央，湘帘高捲开堂皇。","长吟挥汗苦炎热，窗明几净空徬徨。","一歌再鼓不成曲，陈陈相因惭秕糠。","捧君佳什回环读，幅幅击拊如琳琅。","韩潮苏海走气势，子云相如兼骚庄。","泛揽群言入炉冶，胸中鼓铸呈精光。","纪梦两篇最奇绝，游仙何必推曹唐。","瑰丽离奇不可状，恍若洪厓浮邱来扶将。","何幸拉我登天阙，龙腰鹤背偕翱翔。","知君本是谪仙客，故尔精神结注非寻常。","长歌娓娓数百语，触手妙绪何汪洋。","白衣苍狗寄幽远，天空海阔怀莽苍。","忽尔鸢鱼足儒理，深衣大带垂堂堂。","忽尔高举如仙人，瑶草玉树琪花香。","忽尔枯寂似释子，萧然钵笠来西方。","变幻百怪难拟议，笔锋到处生光芒。","其馀诸什烂云锦，纷纷掩映争辉煌。","低回我自愧形秽，不敢踵韵期颉颃。","忆我学诗三十载，半生师友多江乡。","吴山楚水贮行橐，江花汀草皆文章。","好风一苇渡洋子，叩舷六代悲兴亡。","北涉黄河望沧海，天地乃尔多包藏。","东登泰岱观日月，六合极目空微茫。","乃入都会见钜丽，始知陆海真洪荒。","陆离熣灿杂五色，迷人欲使双睛盲。","开拓心胸竟何似，徒令跋涉劳梯航。","嗒焉归来驻蓬荜，一邱一壑聊徜徉。","闭门寡侣愈孤陋，骚坛无事争雄强。","今岁与君建旗鼓，彼此破斧或缺斨。","连篇累牍不相下，争排笔阵驱词场。","君才既富性复敏，气盛不拘言短长。","我范驰驱计步武，鸟蛇前后求安详。","守正自能待劲敌，出奇制胜殊未遑。","自春徂夏数十作，未尝放笔为歌行。","此调不谈亦已久，但觉蹇涩非铿锵。","自朝至于日中昃，书成屋角飞斜阳。","掷笔朗吟自斟酌，暮天习习薰风凉。","愿将此作质法眼，勿为世俗之见徒揄扬。"]},{"t":"渡辽河","f":"七言绝句","c":["漠漠平沙日影低，西风一苇渡辽西。","长安怕醒深闺梦，打得黄莺不敢啼。"]},{"t":"晓行","f":"七言绝句","c":["树杪秋红缀晓霞，西风萧瑟下芦花。","愁人多少关山梦，残月光中到海涯。"]},{"t":"送黎乐安归越南八首 其一","f":"七言绝句","c":["诏许羁臣故国回，天书一纸下三台。","晓来跪听堂皇下，怪底镫花昨夜开。"]},{"t":"送黎乐安归越南八首 其二","f":"七言绝句","c":["半生已分老东辽，赖有方书破寂寥。","此日来归真意表，岂惟没齿感皇朝。"]},{"t":"送黎乐安归越南八首 其三","f":"七言绝句","c":["太和堂上正三春，把笔倾杯两意亲。","毡笠羊裘心自远，知君不是等閒人。"]},{"t":"送黎乐安归越南八首 其四","f":"七言绝句","c":["缟纻相亲十二年，东风昨夜有啼鹃。","短吟惜别无奇句，几度挥毫意惘然。"]},{"t":"送黎乐安归越南八首 其五","f":"七言绝句","c":["琐尾流离痛从亡，沈沙折戟战场荒。","英山岚翠琤江水，回首当年总断肠。"]},{"t":"送黎乐安归越南八首 其六","f":"七言绝句","c":["云山几万隔黔滇，铜柱西南更有天。","日暮怀君舒望眼，断魂祇在夕阳边。"]},{"t":"送黎乐安归越南八首 其七","f":"七言绝句","c":["杯酒相邀强作欢，贺君不敢泪阑干。","黯然已是悲生别，况复音书一纸难。"]},{"t":"送黎乐安归越南八首 其八","f":"七言绝句","c":["赠君玉玦当刀环，去去行旌大惠山。","为嘱西风秋夜里，好吹清梦度榆关。"]},{"t":"题画兰送范近光","f":"七言绝句","c":["闻君十载戍龙江，知是徵兰梦渺茫。","此日承恩归故国，声华应胜畹花香。"]},{"t":"村中","f":"七言绝句","c":["柳阴冉冉乳鸦啼，掩映柴扉拂水低。","何处篴声深绿里，随风断续过桥西。"]},{"t":"寄普遐亭 其一","f":"五言律诗","c":["风流含大雅，吾爱普遐亭。","笔底开千嶂，行间醉六经。","联吟听夜雨，共立数春星。","何日同携手，重倾竹叶青。"]},{"t":"寄普遐亭 其二","f":"五言律诗","c":["目断燕云远，残阳带晚天。","深情虽欲寄，寸楮未能传。","六月沧溟息，中秋桂树妍。","知君驱骥足，已执祖生鞭。"]},{"t":"修理先君子茔墓","f":"五言律诗","c":["佳城凝山脉，长垣绕墓门。","鸠工劳相度，继绪赖儿孙。","候雁惊霜信，秋虫泣草根。","音容何处是，野树掩黄昏。"]},{"t":"晚眺","f":"五言律诗","c":["村炊敛暮烟，小立晚风前。","落照收残雨，凉云带远天。","山空秋漠漠，溪涨水涓涓。","徙倚青松树，长吟独悄然。"]},{"t":"寄慰遐亭妹丈下第","f":"古风","c":["李廌居然失主司，北平飞将数尝奇。","才高岂遂文憎命，器大应知用有时。","??情怀期视履，沈潜意气且删诗。","遥看来岁清秋月，折取蟾宫第一枝。"]},{"t":"北塔","f":"七言绝句","c":["崔巍古塔薄云高，顶上天风振海涛。","宝月满轮悬北极，大千世界入秋豪。"]},{"t":"懿路道中","f":"七言绝句","c":["挹娄城北晓寒多，霜重羔裘染素罗。","断塔半留残月影，朔风刮面度泛河。"]},{"t":"晓行蒲河道中","f":"七言绝句","c":["雪压征尘冷不飞，村墟处处闭柴扉。","一鞭遥指辉山影，缥缈双峰锁翠微。"]},{"t":"冬夜感怀诸友","f":"七言律诗","c":["怀人独对一镫青，寒气侵窗逼画屏。","万叠云山新旧雨，卅年魏梦短长亭。","波涛无路通双鲤，零落还愁剩晓星。","吟望几多离索感，萧萧风雪打疏棂。"]},{"t":"岁暮南村归","f":"七言绝句","c":["冈峦积素雪漫漫，古径凝冰策马难。","得句欲吟吟不得，北风酸鼻逼人寒。"]},{"t":"正月十日偶成","f":"七言律诗","c":["天街又见市春镫，丽日晴烟瑞霭凝。","微度和风门燕舞，乍回阳气纸鸢腾。","鸡皮不共韶华好，马齿徒随日月增。","时节惊心聊取醉，银杯有酒大如升。"]},{"t":"春日","f":"七言律诗","c":["霭霭和光景物韶，宜人为最是春朝。","垂杨枝共东风软，小沼冰随腊雪消。","瓦雀争鸣喧暖日，纸鸢得意入晴霄。","化机活泼天怀畅，曳屐閒行过石桥。"]},{"t":"送朝鲜使臣李鲁山高兼之金清山诸君","f":"七言律诗","c":["和光雅度座生春，醉我名言似饮醇。","笔底莲花开妙舌，胸中菱镜绝纤尘。","延陵在古多君子，瀛海于今有故人。","欲问清辉何处是，神嵩东畔望冰轮。"]},{"t":"得李鲁山金清山见和之作却答","f":"七言律诗","c":["皇华嘉拜幸如何，得得归骢乐意多。","白岳晴岚迎使节，绿江秋浪度仙艖。","钩银画铁今难继，水鸟山云古不磨。","我愧阳春无妙曲，巴吟远向郢中歌。"]},{"t":"望虹螺山","f":"七言绝句","c":["群峰负势竞嵯峨，天半岚光翠霭多。","晓色宜人双眼豁，吕洪山外看虹螺。"]},{"t":"阻雨宿三里桥","f":"七言绝句","c":["风雪陵人气欲吞，重阴漠漠冻云昏。","无眠茅店萧条甚，独对寒檠锁断魂。"]},{"t":"抱关岭","f":"七言律诗","c":["冈峦磅礴复回环，石磴崚嶒未易扳。","后所屏藩开巨镇，长城襟带拥雄关。","双溪夹绕奔沧海，一岭横盘锁乱山。","故垒风云怀往事，尚教吟望壮衰颜。"]},{"t":"永平怀古","f":"七言绝句","c":["负海凭山古北平，汉时飞将气犹生。","谁知不具封侯骨，没羽空存石虎名。"]},{"t":"玉田道中","f":"七言绝句","c":["凝膏冷爓夜迢迢，笼烛鸣鸾驿路遥。","残梦迷离落何处，晓风吹过彩亭桥。"]},{"t":"晓行","f":"七言绝句","c":["唱罢村鸡夜已阑，霜风刮面敝裘寒。","朝霞有意迎归骑，一片轻红上马鞍。"]},{"t":"首山","f":"七言绝句","c":["三峰倚汉翠屏开，峰顶犹存古燧台。","白首老兵言往事，少年曾拾宝刀来。"]},{"t":"望虹螺山","f":"七言绝句","c":["天收海雾拥朱轮，习习微风起细尘。","数朵芙蓉天外落，虹螺山翠笑迎人。"]},{"t":"题画","f":"七言绝句","c":["有客携琴策蹇归，奚童却扫闭柴扉。","西窗小醉斜阳暖，一任阶前落叶飞。"]},{"t":"宿双峰寺","f":"七言律诗","c":["南峰烟接北峰阴，树影迎车暮色沈。","夜磬一声闻梵贝，春潭千尺净尘心。","幻缘结梦何时醒，妙境宜人得契深。","山月满窗清不寐，长吟无复睡魔侵。"]},{"t":"访李松峰维翰","f":"七言绝句","c":["水映霞光浪影红，伊人门在夕阳东。","兴来不用山阴棹，芳径携筇趁晚风。"]},{"t":"为立亭十二弟题画兰 其一","f":"七言绝句","c":["白石清溪寄迹深，红芽惟傍碧苔阴。","洛阳锦绣知多少，谁向空山结素心。"]},{"t":"为立亭十二弟题画兰 其二","f":"七言绝句","c":["擎空峭壁对晴晖，附有芳兰倚翠微。","一霎天风岩畔过，幽香合向碧霄飞。"]},{"t":"画兰","f":"五言绝句","c":["写兰不求似，不似亦非兰。","似与不似间，素心千古寒。"]},{"t":"梦鹤轩夜坐","f":"七言律诗","c":["幽斋独坐夜融融，弄影檐花簌簌红。","树密恰容窗纳月，帘疏不碍座当风。","心涵静契神俱寂，思入虚灵念欲空。","何处更寻仙境界，此身今在玉壶中。"]},{"t":"雨后郊行","f":"五言律诗","c":["马足青泥滑，迎人径草幽。","远天拖雨脚，残日破云头。","水泛山溪阔，烟低野树稠。","农夫看得意，蓑笠叱黄牛。"]},{"t":"学廨漫吟 其一","f":"七言绝句","c":["潾潾泮水细生波，绿影参差掩芰荷。","斗室最宜新雨后，薰风凉到北窗多。"]},{"t":"学廨漫吟 其二","f":"七言绝句","c":["断云拖雨过高城，帘捲虚斋素壁明。","绿树绕檐人寂寂，独凭小榻听禽声。"]},{"t":"寄答梁鹤庄 其一","f":"七言绝句","c":["三十年来感逝波，浮云身世变更多。","故人零落青门旧，白发盈头唤奈何。"]},{"t":"寄答梁鹤庄 其二","f":"七言绝句","c":["曾同诸子共趋庭，朝退追随过引亭。","杖履于今魂梦里，不堪回首忆横经。"]},{"t":"寄答梁鹤庄 其三","f":"七言绝句","c":["骑箕化鹤已神仙，两母云山隔一天。","安得老人相晤对，与君同侍话当年。"]},{"t":"寄答梁鹤庄 其四","f":"七言绝句","c":["司鹾作宰为家贫，清俸重颁足养亲。","枢要遗徽今具在，期君衣钵继先人。"]},{"t":"寄答梁鹤庄 其五","f":"七言绝句","c":["法书分我浣溪笺，属领风花雪月权。","俗骨自来医不得，此中清旷恐无缘。"]},{"t":"寄答梁鹤庄 其六","f":"七言绝句","c":["海角迢迢忆索居，故人应亦念吾庐。","见君不待梁头月，斗室常悬尺素书。"]},{"t":"暮行山中","f":"五言律诗","c":["曲折寻幽径，青山拥去鞭。","溪深新雨后，草乱晚风前。","残照下高树，暮鸦归远天。","柴门何处是，漠漠隔炊烟。"]},{"t":"一月以来连绵霪雨闷中成句","f":"七言律诗","c":["匝月曾无五日晴，霪霖何以慰舆情。","湿云低欲齐檐堕，积水深恒没砌平。","泥落空梁饥燕语，烟销沈灶怒蛙鸣。","疏棂半启书床暗，吟望元穹太瘦生。"]},{"t":"蒿镫次立亭十二弟韵","f":"七言律诗","c":["折得蒌蒿植院庭，乱悬香炷火光荧。","迷离珠树迎人艳，缥缈檀香拂面青。","□地欲成三里雾，映空疑落满天星。","却猜月黑雷塘夜，散出隋宫万斛萤。"]},{"t":"默坐","f":"五言律诗","c":["默坐心神静，虚窗片月悬。","帘波三尺水，炉篆一痕烟。","凉露坠高树，素河明远天。","此中清妙境，无隙入尘缘。"]},{"t":"齿落","f":"七言律诗","c":["颊辅相依五十秋，一朝辞去少迟留。","咀含曾未知书味，摇落由来逊舌柔。","已向膏粱恣大嚼，不随林壑漱清流。","于今尔我无关涉，征汇毋贻同类忧。"]},{"t":"题醉仙图","f":"七言绝句","c":["洞里烟霞岁月多，桑田几见涌沧波。","先生不是贪酣醉，自向乾坤养太和。"]},{"t":"怀朝鲜李鲁山金清山诸君","f":"七言律诗","c":["庭树风凉又仲秋，去年同此话瀛洲。","辞华各擅无双艳，品格都居第一筹。","鸭绿江涛流别恨，神嵩山月照离愁。","贲然何日重酬酢，共解相思溯旧游。"]},{"t":"秋夜大风继之以雨甚寒","f":"七言律诗","c":["风伯号空逞怒威，青镫短榻闭双扉。","骚人影共秋花瘦，落叶声兼冻雨飞。","万里有书鸿雁冷，九霄无路梦魂归。","醉吟拟欲驱寒去，玉粟生肌酒力微。"]},{"t":"拟古 其一","f":"五言古诗","c":["高楼有美人，容华明月光。","丹黄无所施，缟素为衣裳。","空帷独自悲，徘徊下高堂。","愿得一心人，相共成七襄。","殷勤结女伴，朝夕相颉颃。","学为好笑嚬，亦为时世妆。","无如非本真，徒劳回寸肠。","敛手谢流辈，愿言归洞房。"]},{"t":"拟古 其二","f":"五言古诗","c":["洞房有鸣琴，朱弦多古音。","一鼓再三叹，聊以慰悲心。","明月照素颜，清风吹缟衿。","徘徊复徘徊，夜寒更漏沈。","青春不我留，霜华双鬓侵。","盥手理残机，爱此一寸阴。","蛾眉不入时，人情自古今。","修绠汲寒泉，相将此意深。"]},{"t":"拟古 其三","f":"五言古诗","c":["窈窕启明窗，罗帷风自开。","素月西复西，所观殊未来。","置我黄金梭，敛我明镜台。","锦瑟一再弹，弦外有馀哀。","言笑日以远，容华日以摧。","与子结相思，素心终不回。","霜气树高空，木叶飞林隈。","揽衣不成眠，空阁起徘徊。"]},{"t":"秋末暮行山中","f":"七言律诗","c":["到处萧条秋意阑，荻花枫叶已凋残。","烟凝平野山岚紫，风拂疏林日影寒。","新雪销融泥滑滑，远镫明灭路漫漫。","苍茫暮霭迷荒径，赖有星光上马鞍。"]},{"t":"归自南村","f":"五言律诗","c":["归骑成新句，禅关访旧踪。","断碑青藓合，画壁暗尘封。","叶尽山容瘦，云寒雪意浓。","马蹄残日里，缥缈听清钟。"]},{"t":"与从弟德基话旧","f":"七言律诗","c":["瞬息韶华慨逝波，世情几许眼前过。","也知名士尝题凤，不信书生解化鹅。","混俗祇今聊复尔，谋生到此竟如何。","自来白发无公道，偏向愁人顶上多。"]},{"t":"尚铁峰来访","f":"七言律诗","c":["每依斗柄望文軿，忽报柴关小驷停。","魂梦空劳寻酒国，烟花好共叩诗扃。","三春莺侣迁乔木，六月鹏抟息北溟。","此际与君舒别悃，不须重忆短长亭。"]},{"t":"万泉河夜步","f":"五言律诗","c":["月色明如许，幽寻性所耽。","花光浮夜气，星影浸春潭。","古寺清钟歇，长堤野径谙。","携筇吟未已，已过小桥南。"]},{"t":"独酌漫吟","f":"七言律诗","c":["仕为贫驱亦奈何，年华空自悔蹉跎。","人情冷淡黄金尽，诗句苍凉白发多。","混俗祇宜醒且醉，闭关直欲哭当歌。","葛巾且漉新醅酒，小梦迷离养太和。"]},{"t":"感吟","f":"五言古诗","c":["田中植嘉苗，墙头生野草。","人功与地力，无须较多少。","十日不得雨，长空日杲杲。","墙头草正青，田中苗欲槁。","此理殊难测，郁郁伤怀抱。"]},{"t":"途中","f":"五言律诗","c":["野路青山外，孤村白水边。","树迷芳草渡，烟淡夕阳天。","车马劳长道，波涛感逝川。","何如滩上叟，高卧钓鱼船。"]},{"t":"偶感","f":"七言绝句","c":["子晋吹箫便得仙，玉炉金鼎总虚传。","迩来自悟长生诀，祇取莺花乐眼前。"]},{"t":"骆驼","f":"七言绝句","c":["肿背从教辨是非，铁衣曾载美人归。","而今不用驰千里，牧向春郊草正肥。"]},{"t":"秋晓","f":"七言绝句","c":["峭寒入夜逼窗纱，敲彻晨钟静不哗。","老树迷离横瘦影，半天残月听啼鸦。"]},{"t":"暮坐","f":"七言绝句","c":["漠漠秋空雁几行，晚烟浮动月昏黄。","凭窗瘦骨支离甚，落叶风多纸帐凉。"]},{"t":"病中偶成","f":"五言律诗","c":["久病精神减，无心问物华。","目昏看字误，腕弱作书斜。","小径馀残菊，凉烟点暮鸦。","萧萧衰柳叶，历乱打窗纱。"]},{"t":"哭寿安表弟","f":"七言律诗","c":["霜落金台柿叶丹，秋镫相对夜初寒。","君能身作芝兰客，我只竽吹苜蓿盘。","有母存孤生已幸，无儿承后死应难。","空馀匣里端溪砚，鸲鹆双枯泪眼乾。"]},{"t":"秋夜独坐有怀三弟伟","f":"七言律诗","c":["凉云漠漠作清阴，静听閒庭众籁吟。","落叶打窗秋渐老，疏钟敲梦漏初深。","燕台夜雪三年别，闽海西风万里心。","为嘱冥鸿劳寄语，有人天末望乡音。"]},{"t":"雪后行东山道中","f":"七言绝句","c":["积素凝辉远近同，行人直在玉山中。","青光飞出群峰外，寒逼残阳淡不红。"]},{"t":"归自东山","f":"五言律诗","c":["驱车入平陆，人在万山西。","野旷飘风急，云昏落日低。","孤烟横远坞，古渡锁寒溪。","遥指高城近，疏镫树影迷。"]},{"t":"除日得三弟公伟书知暂知瓯宁县事值有海盗蔡牵朱濆之警","f":"七言律诗","c":["南云望断旅鸿疏，一纸飞来正岁除。","五十三龄双雪鬓，七千馀里万金书。","烽传闽海严新令，梦阻仙霞绕故庐。","忆得屠苏谋共醉，寸函相对意何如。"]},{"t":"春雪","f":"七言绝句","c":["风聚春云夜不晴，残更忽觉峭寒轻。","起来却捲西窗看，琼树瑶阶照眼明。"]},{"t":"夜坐怀旧","f":"七言律诗","c":["祇今病骨怯宵寒，料峭风多倚户难。","得句微吟呵冻写，拣书独坐掩镫看。","燕台缟纻流云散，吴院莺花小梦残。","几许旧游都往迹，被裘重忆听更阑。"]},{"t":"春夜漫吟","f":"七言律诗","c":["九十春光一月过，东园花信竟如何。","层云不动天将雪，小沼初融水欲波。","剪烛无眠谋小醉，披书有契发长哦。","不愁鬓发随时短，却喜推敲得句多。"]},{"t":"独坐感怀","f":"五言律诗","c":["猎猎东风急，云开雪意阑。","耽吟忘坐久，多病怯春寒。","白发随才短，愁肠赖酒宽。","徘徊看日影，已过石阑干。"]},{"t":"村中","f":"七言律诗","c":["东风轻压暖烟低，径草青才没马蹄。","溪水乍深消腊雪，土膏初润试春犁。","花枝留客谋酣醉，山色宜人待品题。","倚杖柴门残照里，依依杨柳暮鸦啼。"]},{"t":"行路谣","f":"古风","c":["山重重，水迢迢，云峦缥缈山路遥。","浪游汗漫亦何为，舟车烦殆心旌摇。","危峰巀嶪群山高，怪木蒙密石硗硗。","猩猩啼月虎夜号，白日未匿来山魈。","江湖灏渺多波涛，长风驾浪声萧萧。","排空出没鼋鼍蛟，神龙变幻为氛妖。","游子到此意气尽，欲行不行空悲骚。","故人曾结生死交，赠以龙纹双宝刀。","锋能切玉灿如雪，光怪所及神鬼逃。","任使万里翔与翱，山高水深无阻挠。","吁嗟乎禹鼎沈沦不可见，魑魅魍魉谁不遭。","人生切勿轻游遨，为君一歌行路谣。"]},{"t":"送叶逸林南归写兰于扇赠之 其一","f":"七言绝句","c":["风尘弹指十年馀，秋月春花忆旧庐。","沧海片帆君自去，故人萧索竟何如。"]},{"t":"送叶逸林南归写兰于扇赠之 其二","f":"七言绝句","c":["离心已逐海云飞，欲谱骊歌笔力微。","短箑幽兰三两叶，香风万里送君归。"]},{"t":"柬金尚诸君","f":"五言绝句","c":["轻风扫绿苔，为待故人来。","展榻启明窗，小园花正开。"]},{"t":"学课官生作","f":"七言律诗","c":["短檐素壁纸窗明，弦诵居然继古声。","训迪久惭唐博士，雍容何让鲁诸生。","书因得解花同笑，心至忘机鸟不惊。","我自疏慵叨月俸，难将多士贡司成。"]},{"t":"自遣 其一","f":"七言律诗","c":["静中日月似年长，世事閒观淡欲忘。","天地有情容我拙，春秋多暇为诗忙。","聊将薄俸谋甘旨，敢以疏材企栋梁。","案上好书樽内酒，山园时荐野蔬香。"]},{"t":"自遣 其二","f":"七言律诗","c":["曰归卅载卧烟霞，斗室栖迟兴转赊。","细雨恰生帘外草，好风不落案头花。","浮云来去成今古，往事兴衰自岁华。","未得忘情如太上，夜深有梦到天涯。"]},{"t":"哭林翁四首 其一","f":"七言绝句","c":["君已神归入杳冥，夜窗犹忆说天星。","青山原自堪埋骨，祇是无人解葬经。"]},{"t":"哭林翁四首 其二","f":"七言绝句","c":["寻山问水尚精神，矍铄哉翁近九旬。","一笑掀髯心自得，不离奇处是天真。"]},{"t":"哭林翁四首 其三","f":"七言绝句","c":["钩深守约不同尘，三法持衡妙四真。","多少佳城亲窆穸，埋君今日是何人。"]},{"t":"哭林翁四首 其四","f":"七言绝句","c":["理气真源已尽窥，惜乎宛转合时宜。","金针未得斯人度，几卷残书付与谁。"]},{"t":"官学斋前植柳","f":"七言律诗","c":["折来杨柳带轻烟，种向虚斋小牖前。","干弱每须扶短竹，土松最喜沃清泉。","敢期棠荫留遗爱，聊拟槐街企昔贤。","为语庭阶桃李树，风流张绪在当年。"]},{"t":"周爽亭印谱","f":"五言古诗","c":["南风吹墨云，急雨飞檐溜。","何以破岑寂，徘徊对圭窦。","铁峰遗小册，云是爽亭授。","丹泥印文字，淹雅亦朴茂。","古篆列鼎彝，居然秦汉旧。","大者或如栗，小者或如豆。","从容游刃馀，翔翥如灵鹫。","奇崛作古拙，怒蹲如猛兽。","爽亭本快士，岂屑俗儒陋。","驰驱于规矩，不为规矩囿。","乃以扛鼎力，寸刀腕下奏。","我昔学剜印，文何不可遘。","锟刀与花乳，时时在怀袖。","亦欲集卷轴，迄今未能就。","迩来目益衰，毫芒昧清昼。","得君此印迹，展转再三复。","愿君神此技，上追斯与籀。"]},{"t":"乌拉草","f":"七言律诗","c":["青青有草碧江边，遂尔名因乌拉传。","细叶秋丛身似束，清砧夜杵软如绵。","履霜制葛原难任，卫足倾葵仅自全。","南国久闻称不借，禦寒较此拟天渊。"]},{"t":"虚堂","f":"七言绝句","c":["虚堂昼静独徘徊，帘幕无人风自开。","花雨不知何处落，乱红飞舞上青苔。"]},{"t":"归舍 其一","f":"七言绝句","c":["自饱园蔬脱粟香，午馀磅礴倚绳床。","疏帘一任风来去，领取茅斋北牖凉。"]},{"t":"归舍 其二","f":"七言绝句","c":["长昼无人静闭门，雨馀庭树锁黄昏。","月轮影落平池里，吟得新诗教小孙。"]},{"t":"送马朗山司寇","f":"七言律诗","c":["沈水才经洗辙尘，天风又复促征轮。","秋官正切沾时雨，河政旋看寄老臣。","赠别自饶新笔墨，论交犹是旧情亲。","欲知此后相思梦，祇在淮黄泗济滨。"]},{"t":"题画兰","f":"古风","c":["不画凡花只画兰，丰神无异作书难。","如今也看??好，笑未当初学牡丹。"]},{"t":"读王瑶峰先生游千山诗","f":"七言律诗","c":["梦想千华廿七年，未能曳屐访林泉。","却看字字波翻峡，似见峰峰剑倚天。","云起空濛晴作雨，瀑飞灒漫水成烟。","何时碑拓香岩寺，得结灵山翰墨缘。"]},{"t":"七夕词","f":"七言绝句","c":["星影潜移碧汉沈，露凉风净夜初深。","年来不乞天孙巧，閒却朱丝七孔针。"]},{"t":"王义门以其大父瑶峰前辈诗稿属为校订因题卷后","f":"七言律诗","c":["前辈遗音尽典型，萧然不以一钱名。","落花啼鸟怡天性，流水行云寄世情。","大雅声华钟鼎重，小巫评骘羽毛轻。","我生较晚兼随宦，未向龙门获识荆。"]},{"t":"题云随诗稿后","f":"七言律诗","c":["开编渺渺独愁余，竟此生平水月虚。","清气盘旋仙露润，高怀飘逸绛云舒。","金泥恨未承家法，玉种欣能读父书。","鸿爪祇今堪骥附，笛渔小草正相如。"]},{"t":"书怀","f":"七言律诗","c":["日见头颅白雪侵，韶华瞬息度驹阴。","半生书剑无长技，万里金兰有素心。","结习竟难忘翰墨，前途久不计升沈。","新诗且喜装成卷，未负当年好苦吟。"]},{"t":"九日","f":"七言律诗","c":["九日当年兴亦豪，祇今懒惯怯登高。","黄花纵遣簪双鬓，白发居然过二毛。","酒醉恐人讥落帽，才疏自古怕题糕。","知君携侣龙山去，我待清词下浊醪。"]},{"t":"秋夜既寝醒见窗月大佳起玩成咏","f":"五言古诗","c":["梦回虚白生，华月满窗纸。","爱此烂银光，披衣更深起。","树影落参差，错认一庭水。","凉风袭襟裾，清气沁肌髓。","万籁寂无声，心在空灵里。"]},{"t":"怀尚铁峰","f":"七言律诗","c":["花骢去去夏徂秋，闻说泥涂过挹娄。","瑟瑟西风吹别梦，萧萧明月照离愁。","酒杯欲共谁斟酌，诗卷惟馀自校雠。","千五百言劳远寄，龙山麟水少同俦。"]},{"t":"义门和即事诗次答","f":"七言律诗","c":["风流自是旧王家，促膝清言北斗斜。","玉粒惭无香稻饭，竹炉赖有碧螺茶。","大能稽古从吾好，小不逢时漫自嗟。","投我新诗盈卷轴，乱飞五色笔头花。"]},{"t":"闻金銮坡获隽书寄铁峰","f":"七言律诗","c":["故人拔帜已先登，我念君犹未共升。","运笔天机真烂漫，立言风度最端凝。","莫云造化能为幻，所信文章自有凭。","六月北溟看暂息，行将九万待云鹏。"]},{"t":"怀秀岚銮坡铁峰诸君","f":"七言律诗","c":["诸君天质尽超群，叩我时争字句新。","心以无猜成妙契，交因耐久得情亲。","飞声黉序称三友，振翮云霄已一人。","老马自惭途未识，几劳屐齿印苔茵。"]},{"t":"题画兰","f":"七言绝句","c":["清露涓涓晓未乾，轻风细细绕雕栏。","写成不必幽人佩，只此丰标秀可餐。"]},{"t":"山村","f":"七言绝句","c":["细草危桥一径斜，柴门高柳是谁家。","蕨羹麦饭无馀事，閒看溪边桔梗花。"]},{"t":"晓起","f":"五言律诗","c":["窗纸渐生白，披衣当户前。","离离分曙色，漠漠对凉天。","残月淡花影，晓风开柳烟。","襟裾馀爽气，徙倚独萧然。"]},{"t":"冬日行山中","f":"五言绝句","c":["木叶捲寥空，飕飗起朔风。","万峰寒翠里，一点夕阳红。"]},{"t":"题兰","f":"七言律诗","c":["乱吐红芽破碧苔，空山生小远蒿莱。","虽无桃李春风面，会有声华御史台。","结佩未须湘水去，掬香都入砚池来。","移将九畹神仙种，叶叶花花笔底开。"]},{"t":"纂辑诗钞自识","f":"古风","c":["君不见高山大渊置姓氏，古人好名乃如是。","又不见载笔纪传成史书，恐名不彰以没世。","自晋唐宋递元明，或著诗篇或琐志。","古人结习不可除，今者后人宁有异。","余亦吟诗千馀篇，共成五万二千字。","吾闻太上立德次立功，垂之空言嗟罔济。","况乃风云月露词，虽工仅号雕虫技。","抑闻诗以道性情，或云古者诗言志。","葩经三百十一篇，大抵发愤所为制。","最是劳人思妇辞，等閒谣谚偏姿致。","当时出语岂求工，天籁之鸣不可企。","后世纷纷无病呻，乃尚浮文争绮丽。","章求典赡句求丰，往往誇多翻害义。","溯从十六窃为诗，其时正课攻时艺。","蝇头小字累成编，不令人见藏经笥。","及今白发已盈头，犹自耽唫如往岁。","暑日寒宵自较雠，缥缃似较牛腰细。","灾梨祸枣愧无资，用托中书为编次。","虽无功绩似前人，聊纪生平所遭际。","自少及壮至于今，纪月编年如掌记。","其间三十有六季，纷纷人事填胸臆。","曾上金台登岱宗，车烦马殆燕齐地。","南下黄河渡大江，震泽扁舟臻海澨。","思亲怀友托讴吟，吊古凭今动幽思。","春花秋月寄閒情，对酒当歌吐奇气。","割裂篇章耻饾饤，堆积群书陋獭祭。","固无奇语泣鬼神，亦时机轴生新意。","半生心力在于斯，不忍鸿毛等轻弃。","忆从归我旧蓬门，不获名流相砥砺。","造化弄人多坎坷，幸未执鞭隳此事。","晚年鸣铎注一官，居然不食如匏系。","散衙退息有馀閒，每每推敲再三四。","于今会萃辑成书，裁锦装函自珍秘。","吁嗟乎少时妄念颇亦奢，而今不复思功利。","只此区区数卷诗，用以遗留于后嗣。","其幸或为世所传，其幸后昆能缵继。","不幸或生愚子孙，覆酱糊墙任委置。","即今散失或不收，转愁后辈生訾议。","吁嗟乎悲从中来写我心，叙作长篇聊自识。","剪烛高歌歌即书，琢句雕章非所计。"]},{"t":"寒夜独坐有怀三弟公伟","f":"七言律诗","c":["树影朦胧淅沥风，闭关独坐寂寥中。","课诗遣夜葵笺碧，煮茗消寒炭火红。","魂梦五年依海月，音书万里望春鸿。","遥闻巨盗膺天殛，曾否同襄尺寸功。"]},{"t":"夜行村中","f":"五言律诗","c":["荒径迷衰草，驱车独夜行。","断冰迎月白，野烧入昏明。","风力侵衣劲，霜花拂面轻。","前村知不远，隐隐辨人声。"]},{"t":"题雁有怀舍弟 其一","f":"七言绝句","c":["蓼花零落荻花开，江上西风雁又回。","我有鹡鸰千万里，何时天末寄书来。"]},{"t":"题雁有怀舍弟 其二","f":"七言绝句","c":["塞草初黄夜有霜，秋空云净雁成行。","几回啼醒他乡梦，嘹呖声中月满床。"]},{"t":"雪夜忆旧","f":"七言绝句","c":["雪花积素广庭宽，晴后昏黄月色寒。","记得老梅低瘦影，一枝横压石阑干。"]},{"t":"过双峰寺","f":"七言律诗","c":["一双螺髻倚云端，岚气飞空浸碧湍。","地暖草芽先欲吐，峰高雪影未全残。","金铃语断东风细，石鼎香消夜雨寒。","几度到来难便去，何时结屋倚松峦。"]},{"t":"怀芗坪三弟","f":"五言律诗","c":["纸窗风瑟瑟，逼幕峭寒生。","忽听中宵雁，深关万里情。","戍楼低晓月，画角动春城。","吟望闽天远，凭谁问海程。"]},{"t":"寄朝鲜李鲁山金清山高兼之诸君","f":"七言律诗","c":["吟望东瀛璧月圆，诗成附鹤寄诸仙。","开函应是才三月，忆别何期竟五年。","会有干旄联旧雨，宁无翰墨续前缘。","尺书不尽相思意，珍重封题独惘然。"]},{"t":"出东郊","f":"七言律诗","c":["暖云烘日晓霞红，吹面轻寒料峭风。","隔屋乳鸦藏弱柳，避人归雁入高空。","溪流欲畅冰初泮，野草才萌土未融。","再到似应春色好，拟将吟醉艳阳中。"]},{"t":"孙笠山谓余诗多山林气吟此奉答","f":"五言律诗","c":["谓我山林气，山林别有春。","祇愁悲大隐，未获养天真。","冷署分官席，炎涂逐俗尘。","自因寒素久，台阁岂同纶。"]},{"t":"忆亡内 其一","f":"五言绝句","c":["人世春如梦，繁花依旧春。","如何花满树，不见种花人。"]},{"t":"忆亡内 其二","f":"五言绝句","c":["不见种花人，花落纷如雪。","红雨滴青苔，点点胭脂血。"]},{"t":"多风漫吟","f":"七言绝句","c":["愁绝芳林日日风，萧斋坐我寂寥中。","捲帘懒向苔阶看，花雨平堆一寸红。"]},{"t":"夜雨","f":"七言律诗","c":["风吹海雾作轻阴，树色迷蒙暮影深。","万里暖云春漠漠，一天细雨夜沈沈。","看花拟欲燃红烛，敲句无嫌拥翠衾。","却望朝来晴旭好，青山几处待幽寻。"]},{"t":"寄尚铁峰 其一","f":"七言绝句","c":["书城日拥自嚣嚣，痛饮能教块垒销。","有笔如君堪售赋，等閒莫漫事渔樵。"]},{"t":"寄尚铁峰 其二","f":"七言绝句","c":["同人三五尽飞声，桂苑槐阶踏屐行。","岂待敛藏三载后，一鸣方始万人惊。"]},{"t":"寄尚铁峰 其三","f":"七言绝句","c":["望子轺车秋复春，明蟾十五度如轮。","如何学得东山卧，不向西南问故人。"]},{"t":"寄尚铁峰 其四","f":"七言绝句","c":["应是君诗别有编，我诗亦复辑多篇。","何时坐我松花阁，相共推敲绿酒前。"]},{"t":"五月颇寒口号一绝","f":"七言绝句","c":["五月居然未释裘，凄风细雨共飕飕。","富春老子非多事，谁谓因名下钓钩。"]},{"t":"题画 其一","f":"七言绝句","c":["好是青春二月初，远山明靓绿阴疏。","幽禽啼后閒窗静，花影满楼人读书。"]},{"t":"题画 其二","f":"七言绝句","c":["浓阴一片落窗前，漠漠澄波浸碧烟。","草阁江深寒正好，蒲帆谁系米家船。"]},{"t":"憩双峰寺","f":"七言律诗","c":["净土无忧暑气侵，坐来清秘涤尘襟。","水穿石隙笙簧细，烟积山坳翡翠深。","疏磬一声虚阁静，远岚四起夕阳沈。","诛茅亦有幽栖意，暂倚云关寄短吟。"]},{"t":"题兰","f":"七言绝句","c":["习习东风空谷春，等閒原不惹氛尘。","猗兰操后谁相识，祇有灵均是解人。"]},{"t":"暮晴感怀","f":"七言律诗","c":["小院无尘静不哗，萧萧庭树集归鸦。","乍开晴色收残雨，为捲西窗看落霞。","暮霭渐迷深径草，凉风欲老绕篱花。","閒愁底事难驱遣，多是怀人感物华。"]},{"t":"怀香坪三弟","f":"五言古诗","c":["迢迢复迢迢，相去万里遥。","子在南闽中，桑梓乃东辽。","明月照相思，徘徊已中宵。","相望不相闻，霜空素影高。","羡彼云中雁，行行翔以翱。","羡彼庭下荆，比比枝附条。","古人重离别，情非儿女曹。","所重笃天伦，故以戒游遨。","或云丈夫身，耿耿志云霄。","尔我迫饥寒，区区谋斗筲。","忆昔在京华，别泪湿绨袍。","我东子则南，音问颇寥寥。","云中道路长，谁为陟岧峣。","经年或一书，每恨阻鸿毛。","安得如黄鹄，振翮归崇朝。","安得化游鱼，一溯剑津涛。","妄念逐心生，怀思空自劳。","何以解繁忧，聊以酌芳醪。","把酒发浩歌，不复事推敲。","愿言托长风，寄音闽海潮。"]},{"t":"春夜漫成","f":"七言律诗","c":["微雪初晴下夕舂，薄寒渐减气和雍。","虚阶土润轻尘少，小榻人閒倦态慵。","烟度柳丝风细细，冰消池水月溶溶。","一瓯薄醉浑无事，卧听青云寺里钟。"]},{"t":"登石台峰","f":"五言律诗","c":["杖策登山顶，天风鼓敝裘。","唾沾飞鸟背，袖拂乱云头。","青霭群峦合，澄波一水流。","湾环含雉堞，倒浸石城楼。"]},{"t":"又一律","f":"五言律诗","c":["峭壁起层层，凌空倚玉屏。","荒台馀石镞，断塔咽风铃。","此日生春草，何年落大星。","低徊无限意，惟有乱山青。"]},{"t":"寄沈明经秀岚 其一","f":"七言绝句","c":["劫来平地幻风波，磨蝎君偏命里多。","片纸衷情言不得，沈郎腰瘦近如何。"]},{"t":"寄沈明经秀岚 其二","f":"七言绝句","c":["传车何事太悤悤，我亦多艰百感丛。","未得一尊留祖道，至今想像梦魂中。"]},{"t":"过东村","f":"七言绝句","c":["芳草沿溪一径斜，绿荫垂柳是谁家。","重来不见桃源树，何处东风问落花。"]},{"t":"与尚铁峰","f":"七言律诗","c":["四壁琳琅绝妙辞，如何梅澥可无诗。","收花入砚香生笔，把酒当轩月满卮。","三日从君藏雾豹，五年期子侍坳螭。","王阳已著先鞭去，正是弹冠共庆时。"]},{"t":"访铁峰不遇","f":"七言绝句","c":["云关寂寂锁葳蕤，驾鹤仙人醉未归。","一树白榆风乍起，青钱扑面学花飞。"]},{"t":"至双峰寺留宿 其一","f":"五言律诗","c":["新雨湿柔沙，清溪绕岸斜。","一轮残日影，几片远天霞。","薄霭生秋草，微风拂径花。","牛羊归牧笛，散入野人家。"]},{"t":"至双峰寺留宿 其二","f":"五言律诗","c":["岚气落高岑，崎岖石径深。","空山惊马足，清磬豁人心。","穿峡泉声咽，凌霄树影森。","松涛传万壑，盈耳海潮音。"]},{"t":"至双峰寺留宿 其三","f":"五言律诗","c":["暂借维摩室，毡分十笏宽。","蕨薇留客意，鸡酒故人欢。","云净秋空碧，山深露气寒。","老僧先入定，独凭石阑干。"]},{"t":"至双峰寺留宿 其四","f":"五言律诗","c":["杰阁倚诸天，当窗璧月圆。","涧光澄夜气，山影淡秋烟。","心目空千古，虚灵净万缘。","非关灰木者，寂灭学安禅。"]},{"t":"双峰寺夜作","f":"七言绝句","c":["夜气澄虚白露清，佛镫冷照石龛明。","西风万壑吹黄叶，飞向山窗作雨声。"]},{"t":"山行遇雨","f":"七言律诗","c":["层岚结翠影霏微，拥作重阴没夕晖。","十里云烟低野路，四山风雨上秋衣。","青泥裹足胶难步，黄叶黏人湿不飞。","蓑笠是谁驱短卫，一鞭得得快先归。"]},{"t":"偕竹町集笠山斋中夜谈","f":"五言律诗","c":["尘事多羁累，今宵共结欢。","漫敲诗律细，不放酒杯宽。","积雪烟光淡，空天月影寒。","丽谯催我急，重惜少盘桓。"]},{"t":"元夜","f":"七言绝句","c":["火树银花十里宽，歌声喧入白云端。","春宵素月无人管，任我凭栏彻夜看。"]},{"t":"题昭君怨","f":"古风","c":["颜色好，黄金少，美人空向胡尘老。","黄金多，罹网罗，黄金虽多终奈何。"]},{"t":"春阴","f":"七言绝句","c":["垂垂庭柳绿新添，风动柔丝绕画帘。","十里春云飞不起，一天雨意压楼檐。"]},{"t":"送人","f":"七言绝句","c":["沾足春泥雪乍消，暖烟晴日永安桥。","骊歌不挽花骢驻，莫遣东风怨柳条。"]},{"t":"读渔洋秋柳诗书后","f":"七言绝句","c":["金粉繁华没夕阳，江皋新染夜来霜。","萧条几树芜城柳，一片秋声入锦囊。"]},{"t":"万泉河散步","f":"七言律诗","c":["不向云关叩佛祠，扶筇沙径自寻诗。","檐铃语细东风软，岸柳阴移午日迟。","为爱青山谋小筑，因临流水立多时。","个中天趣谁能识，吟望春原我独知。"]},{"t":"凌晨出东门","f":"五言古诗","c":["凌晨出东门，春风吹我衣。","明霞照远天，怀袖挹清辉。","高低林莽间，野冢何垒垒。","少老或不齐，贵贱同一归。","或者木为薪，或者仆其碑。","乃有高明子，慷慨有遐思。","思欲乘白云，思欲茹青芝。","蓬莱徒妄传，神仙安可期。","何如卜林泉，饮啄随所宜。","长眺及山颠，高歌溯水湄。","于物无所求，生死任天机。","乘时爱景光，无为逝者悲。"]},{"t":"春晓","f":"五言绝句","c":["东风收雪晴，半夜春寒重。","辨色纸窗明，晓角吹残梦。"]},{"t":"晚步","f":"七言律诗","c":["屐齿閒行印绿泥，石桥南畔觅幽蹊。","烟生野浦澄波远，树绕春城落日低。","万里投书愁雁影，经年怀友怨莺啼。","独吟沙岸浑忘久，新月如钩上钓溪。"]},{"t":"书怀","f":"七言律诗","c":["抱关击柝亦医贫，落落乾坤寄此身。","万里风尘馀白发，一生花鸟负青春。","文章必欲期名世，肝胆休教浪许人。","今日闭门甘伏枥，不堪回首重伤神。"]},{"t":"遣兴","f":"七言律诗","c":["三径芳尘掩绿苔，高堂虚敞四窗开。","风前移榻当轩坐，雨后分花绕砌栽。","乐趣只从閒处领，天机每向静中来。","茶馀睡罢浑无事，吟得新诗手自裁。"]},{"t":"饮酒","f":"七言绝句","c":["伏雨连朝长绿苔，一樽时对北窗开。","谁云酒是消愁物，往事都从醉后来。"]},{"t":"官学偶成","f":"五言律诗","c":["宵来大火流，节物动新愁。","我自甘鸡肋，人将笑虎头。","凉风生远树，残照下高楼。","弹指成何事，萧骚短鬓秋。"]},{"t":"秋雨晚晴","f":"七言绝句","c":["长虹倒挂雨初收，几榻清凉四壁秋。","飞尽碧云天宇净，捲帘风入夕阳楼。"]},{"t":"万泉河登楼感兴","f":"七言律诗","c":["溪上轻烟拂水流，凉波细草乍成秋。","尚馀柳色舒青眼，未放芦花点白头。","西岭云飞归别岫，夕阳人倦倚高楼。","无端百感增萧索，安得忘情似野鸥。"]},{"t":"河上晚步","f":"七言绝句","c":["几株疏柳绕沙堤，野水平桥落照迷。","一片凉烟飞不起，黄昏影里乱鸦啼。"]},{"t":"夜坐","f":"七言绝句","c":["银汉清澄白露凉，西廊月影转东廊。","怀人耿耿不成寐，远雁数声秋夜长。"]},{"t":"浑河即目","f":"七言绝句","c":["漠漠青云掩赤霞，长河风急捲银花。","空林落叶秋无主，一片残阳噪晚鸦。"]},{"t":"读庄子","f":"五言绝句","c":["生死须臾事，彭殇固可齐。","乃知鹏运海，原不异醯鸡。"]},{"t":"早行","f":"五言律诗","c":["远坞鸡初唱，人家户尚扃。","天光沈水白，霜色扑衣青。","大野迷轻霭，寒空带落星。","能知清旷意，不复惮劳形。"]},{"t":"夜行","f":"五言律诗","c":["暝色生岩谷，苍茫路不分。","乱鸦惊夜树，故鬼啸秋坟。","溪阔迷寒渡，山昏锁冻云。","野途谁可问，败叶下纷纷。"]},{"t":"夜坐","f":"五言律诗","c":["焚膏嫌昼短，掩卷一镫凄。","凝雪侵窗白，寒星入户低。","遣怀常觅酒，得句始拈题。","深夜沈疏漏，栖鸡冻不啼。"]},{"t":"永夜静坐颇得幽閒之趣因成二首 其一","f":"五言律诗","c":["人愁冬夜寒，我爱冬夜永。","尘事白昼纷，意念深宵静。","默默一编书，荧荧一镫影。","无殊平旦时，令人发清省。"]},{"t":"永夜静坐颇得幽閒之趣因成二首 其二","f":"五言律诗","c":["高空雪始收，古木风初定。","冷月上疏窗，一片寒光凝。","天机自奕奕，道心常醒醒。","静坐数疏钟，谁与同清兴。"]},{"t":"早醒","f":"七言律诗","c":["微醺醒后烬炉香，纸帐寒宵布被凉。","岁逼常愁双鬓短，梦回不耐五更长。","欲教夜气涵天性，偏是诗魔扰睡乡。","怪底冻鸡啼较早，误人颠倒著衣裳。"]},{"t":"幼孙景逊教以唐诗多而不忘时向老母背诵以博果饵因占四绝句 其一","f":"七言绝句","c":["风雪萧萧独闭门，竹炉拨火酌匏樽。","新诗吟罢先登稿，更写唐诗授小孙。"]},{"t":"幼孙景逊教以唐诗多而不忘时向老母背诵以博果饵因占四绝句 其二","f":"七言绝句","c":["仅是三龄说四龄，丰颐细齿两眸青。","一回雒诵清娱耳，字字珠圆水泻瓶。"]},{"t":"幼孙景逊教以唐诗多而不忘时向老母背诵以博果饵因占四绝句 其三","f":"七言绝句","c":["探得曾萱小睡醒，携书读与老人听。","开奁按句酬佳果，半日支颐笑未停。"]},{"t":"幼孙景逊教以唐诗多而不忘时向老母背诵以博果饵因占四绝句 其四","f":"七言绝句","c":["孙非驽钝母康强，有禄堪支一岁粮。","领得天伦真乐趣，不须人事扰回肠。"]},{"t":"塞下曲","f":"七言绝句","c":["白草黄沙望不穷，旄旗大漠鼓天风。","男儿未带封侯骨，牛斗□横剑气红。"]},{"t":"读唐诗成绝句四首 其一 王颖川","f":"七言绝句","c":["格幽思远迥离群，太息桓灵枢密瞋。","百首宫词娇妩媚，毫端现出美人身。"]},{"t":"读唐诗成绝句四首 其二 李玉溪","f":"七言绝句","c":["玉骨玲珑锦绣肠，齿牙吐出五云光。","合当百宝流苏帐，金鼎常熏海外香。"]},{"t":"读唐诗成绝句四首 其三 李昌谷","f":"七言绝句","c":["万里沧波浩渺中，汀洲何必尽消融。","自将浅易开生面，别有精神李杜同。"]},{"t":"读唐诗成绝句四首 其四 白香山","f":"七言绝句","c":["神仙岂合驻人间，白玉楼成即赐环。","石破天惊难比拟，会须撞碎铁围山。"]},{"t":"十一月十三日忆三弟公伟","f":"五言律诗","c":["为底天南信，愆期不似潮。","离情看素月，清梦度寒宵。","时欲三冬暮，书仍万里遥。","霞杯将介寿，应是忆东辽。"]},{"t":"十二月望观月 其一","f":"五言绝句","c":["碧落群嚣静，清光一片寒。","不知深夜里，耐冷几人看。"]},{"t":"十二月望观月 其二","f":"五言绝句","c":["雪光飞冷艳，霜气淡寒烟。","未肯轻归寝，重看待隔年。"]},{"t":"咏镜","f":"七言绝句","c":["金水精华别有神，不须拂拭绝纤尘。","且将玉匣收全象，莫遣清光远射人。"]}]};